function parseHttpUrl(value, { baseOrigin = "" } = {}) {
  let input = String(value ?? "").trim();
  if (!input) return null;

  if (input.startsWith("/")) {
    const base = parseHttpUrl(baseOrigin);
    if (!base) return null;
    input = `${base.protocol}//${base.hostname}${base.port ? `:${base.port}` : ""}${input}`;
  }

  if (/[\u0000-\u0020\u007f\\]/.test(input)) return null;
  const match = input.match(
    /^(https?):\/\/([^/?#]+)(\/[^?#]*)?(\?[^#]*)?(#.*)?$/i
  );
  if (!match) return null;

  const protocol = `${match[1].toLowerCase()}:`;
  const authority = match[2];
  if (!authority || authority.includes("@") || authority.includes("[")) return null;

  const colonIndex = authority.lastIndexOf(":");
  let hostname = authority;
  let port = "";
  if (colonIndex >= 0) {
    if (authority.indexOf(":") !== colonIndex) return null;
    hostname = authority.slice(0, colonIndex);
    port = authority.slice(colonIndex + 1);
    if (!/^\d{1,5}$/.test(port)) return null;
    const portNumber = Number(port);
    if (portNumber < 1 || portNumber > 65535) return null;
  }

  hostname = hostname.toLowerCase();
  if (
    hostname.length > 253 ||
    hostname.split(".").some(
      (label) =>
        !label ||
        label.length > 63 ||
        !/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i.test(label)
    )
  ) {
    return null;
  }

  const pathname = match[3] || "/";
  const search = match[4] || "";
  const hash = match[5] || "";
  return {
    protocol,
    hostname,
    port,
    pathname,
    search,
    hash,
    username: "",
    password: "",
    href: `${protocol}//${hostname}${port ? `:${port}` : ""}${pathname}${search}${hash}`
  };
}

function normalizeCanonicalUrl(value) {
  const parsed = parseHttpUrl(value, {
    baseOrigin: "https://www.onlinejobs.ph"
  });
  if (!parsed) return "";
  if (parsed.port && parsed.port !== "443") return "";
  const hostname =
    parsed.hostname === "www.onlinejobs.ph"
      ? "onlinejobs.ph"
      : parsed.hostname;
  if (hostname !== "onlinejobs.ph") return "";
  const pathname = parsed.pathname.replace(/\/+/g, "/").replace(/\/$/, "");
  if (!/^\/jobseekers\/job\/[^/]+$/i.test(pathname)) return "";
  return `https://${hostname}${pathname}`;
}

function extractOnlineJobsId(url) {
  const canonicalUrl = normalizeCanonicalUrl(url);
  if (!canonicalUrl) return "";
  const match = canonicalUrl.match(/\/jobseekers\/job\/[^/]*?(\d+)$/i);
  return match?.[1] ?? "";
}

function canonicalJobId(record) {
  const source = String(record.source || "onlinejobs.ph").trim().toLowerCase();
  const sourceJobId = String(record.source_job_id || extractOnlineJobsId(record.canonical_url || record.job_url) || "").trim();
  if (sourceJobId) return `${source}:${sourceJobId}`;
  const canonicalUrl = normalizeCanonicalUrl(record.canonical_url || record.job_url);
  if (!canonicalUrl) return "";
  let hash = 2166136261;
  for (let index = 0; index < canonicalUrl.length; index += 1) {
    hash ^= canonicalUrl.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  const digest = (hash >>> 0).toString(16).padStart(8, "0");
  return `${source}:url:${digest}`;
}

function stateGuard(record) {
  const canonicalId = String(record.canonical_job_id || canonicalJobId(record) || "");
  if (!canonicalId) return "";
  const state = [
    canonicalId,
    String(record.pipeline_status || ""),
    String(record.application_decision || ""),
    String(record.first_reviewed_at || ""),
    String(record.apply_points_used || ""),
    String(record.application_message_strategy || ""),
    String(record.outcome || ""),
    JSON.stringify(Array.isArray(record.outcome_events) ? record.outcome_events : [])
  ].join("\u001f");
  let hash = 2166136261;
  for (let index = 0; index < state.length; index += 1) {
    hash ^= state.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `${canonicalId}|${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

function rankingPriorityValue(record) {
  if (
    typeof record?.opportunity_score === "number" &&
    Number.isFinite(record.opportunity_score)
  ) {
    return {
      value: record.opportunity_score,
      source: "opportunity_score"
    };
  }
  if (typeof record?.match_score === "number" && Number.isFinite(record.match_score)) {
    return {
      value: record.match_score,
      source: "legacy_match_score"
    };
  }
  return { value: 0, source: "missing" };
}

function compareRankingPriority(left, right) {
  const scoreOrder =
    rankingPriorityValue(right).value - rankingPriorityValue(left).value;
  if (scoreOrder !== 0) return scoreOrder;
  const confidenceOrder =
    ({ high: 3, medium: 2, low: 1 }[right.ranking_confidence] ?? 0) -
    ({ high: 3, medium: 2, low: 1 }[left.ranking_confidence] ?? 0);
  if (confidenceOrder !== 0) return confidenceOrder;
  const timestamp = (value) => {
    const parsed = Date.parse(value || "");
    return Number.isFinite(parsed) ? parsed : Number.NEGATIVE_INFINITY;
  };
  const rightPosted = timestamp(right.posted_at);
  const leftPosted = timestamp(left.posted_at);
  if (rightPosted !== leftPosted) return rightPosted - leftPosted;
  const rightCreated = timestamp(right.created_at);
  const leftCreated = timestamp(left.created_at);
  if (rightCreated !== leftCreated) return rightCreated - leftCreated;
  return String(left.canonical_job_id || "").localeCompare(
    String(right.canonical_job_id || "")
  );
}

function parseList(value) {
  if (Array.isArray(value)) return value.filter(Boolean);
  if (!value) return [];
  try {
    const parsed = JSON.parse(value);
    if (Array.isArray(parsed)) return parsed.filter(Boolean);
  } catch {
    // Legacy sheets may use comma-separated values.
  }
  return String(value)
    .split(",")
    .map((part) => part.trim())
    .filter(Boolean);
}

function parseJsonArray(value) {
  if (Array.isArray(value)) return value;
  if (!value) return [];
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed : value;
  } catch {
    return value;
  }
}

function normalizeRuleValue(value, rule) {
  if (!rule || value === "" || value === undefined || value === null) return value ?? "";
  if (rule.type === "number" || rule.type === "integer") {
    const numeric = Number(value);
    return Number.isFinite(numeric) ? numeric : value;
  }
  if (rule.type === "string") return String(value).trim();
  return value;
}

function mergeOutcomeEvents(...collections) {
  const events = new Map();
  for (const collection of collections) {
    if (!Array.isArray(collection)) continue;
    for (const event of collection) {
      if (!event || typeof event !== "object" || Array.isArray(event)) continue;
      const id = String(event.id || "").trim();
      if (!id || events.has(id)) continue;
      events.set(id, { ...event, id });
    }
  }
  const timestamp = (value) => {
    const parsed = Date.parse(value || "");
    return Number.isFinite(parsed) ? parsed : Number.POSITIVE_INFINITY;
  };
  return [...events.values()].sort(
    (left, right) =>
      timestamp(left.at) - timestamp(right.at) ||
      String(left.id).localeCompare(String(right.id))
  );
}

function normalizeLegacyRecord(input, schema, now = new Date().toISOString()) {
  const record = { ...input };
  for (const [legacy, canonical] of Object.entries(schema.legacy_header_mapping ?? {})) {
    if (record[canonical] === undefined && record[legacy] !== undefined) {
      record[canonical] = record[legacy];
    }
  }

  const legacyStatus = String(record.pipeline_status || "").trim().toLowerCase();
  record.pipeline_status =
    schema.legacy_status_mapping?.[legacyStatus] ||
    (schema.pipeline_statuses.includes(legacyStatus) ? legacyStatus : "discovered");
  record.source = String(record.source || "onlinejobs.ph").trim().toLowerCase();
  record.canonical_url = normalizeCanonicalUrl(record.canonical_url || record.job_url);
  record.source_job_id = String(record.source_job_id || extractOnlineJobsId(record.canonical_url) || "");
  record.canonical_job_id = String(record.canonical_job_id || canonicalJobId(record));
  for (const field of schema.string_list_fields ?? ["search_queries", "role_families"]) {
    record[field] = parseList(record[field]);
  }
  for (const field of schema.json_array_fields ?? []) {
    record[field] = parseJsonArray(record[field]);
  }
  for (const [field, rule] of Object.entries(schema.field_rules ?? {})) {
    record[field] = normalizeRuleValue(record[field], rule);
  }
  record.attempt_count = Number.isFinite(Number(record.attempt_count))
    ? Number(record.attempt_count)
    : 0;
  record.alert_attempt_count = Number.isFinite(Number(record.alert_attempt_count))
    ? Number(record.alert_attempt_count)
    : 0;
  record.created_at = record.created_at || now;
  record.updated_at = record.updated_at || now;
  record.source_availability = record.source_availability || "unknown";
  record.profile_version = record.profile_version || "legacy/unknown";
  record.message_profile_version =
    record.message_profile_version ||
    (record.generated_message ? "legacy/unknown" : "");
  record.application_decision =
    record.application_decision ||
    (record.pipeline_status === "applied" ? "applied" : record.pipeline_status === "skipped" ? "skipped" : "");
  record.outcome = record.outcome || "";
  record.manual_action = record.manual_action || "";
  record.state_guard = record.state_guard || stateGuard(record);
  return record;
}

function validateRecordContract(record, schema) {
  const errors = [];
  const fields = new Set(schema?.fields ?? []);
  for (const [field, rule] of Object.entries(schema?.field_rules ?? {})) {
    if (!fields.has(field)) {
      errors.push(`field rule references unknown field: ${field}`);
      continue;
    }
    const value = record?.[field];
    const missing = value === "" || value === undefined || value === null;
    if (missing) {
      if (rule.nullable === false) errors.push(`${field} is required`);
      continue;
    }
    if (rule.type === "enum") {
      if (!rule.values?.includes(value)) errors.push(`${field} has unsupported value: ${value}`);
      continue;
    }
    if (rule.type === "string") {
      if (typeof value !== "string") {
        errors.push(`${field} must be a string`);
        continue;
      }
      if (
        rule.maximum_length !== undefined &&
        value.length > rule.maximum_length
      ) {
        errors.push(`${field} exceeds its maximum length`);
      }
      if (rule.pattern && !new RegExp(rule.pattern).test(value)) {
        errors.push(`${field} has an unsupported format`);
      }
      continue;
    }
    const numeric = typeof value === "number" ? value : Number.NaN;
    if (!Number.isFinite(numeric)) {
      errors.push(`${field} must be a ${rule.type}`);
      continue;
    }
    if (rule.type === "integer" && !Number.isInteger(numeric)) {
      errors.push(`${field} must be an integer`);
    }
    if (rule.minimum !== undefined && numeric < rule.minimum) {
      errors.push(`${field} must be at least ${rule.minimum}`);
    }
    if (rule.maximum !== undefined && numeric > rule.maximum) {
      errors.push(`${field} must be at most ${rule.maximum}`);
    }
  }
  for (const field of schema?.string_list_fields ?? []) {
    const value = record?.[field];
    if (value !== undefined && !Array.isArray(value)) errors.push(`${field} must be an array`);
  }
  for (const field of schema?.json_array_fields ?? []) {
    const value = record?.[field];
    if (value !== undefined && !Array.isArray(value)) errors.push(`${field} must be a JSON array`);
  }
  if (Array.isArray(record?.outcome_events)) {
    const seen = new Set();
    const allowedTypes = new Set([
      "no_response",
      "replied",
      "interview",
      "offer",
      "rejected",
      "correction"
    ]);
    for (const [index, event] of record.outcome_events.entries()) {
      if (!event || typeof event !== "object" || Array.isArray(event)) {
        errors.push(`outcome_events[${index}] must be an object`);
        continue;
      }
      const id = String(event.id || "");
      if (!id || id.length > 256) {
        errors.push(`outcome_events[${index}].id is invalid`);
      } else if (seen.has(id)) {
        errors.push(`outcome_events contains duplicate id: ${id}`);
      } else {
        seen.add(id);
      }
      if (!allowedTypes.has(event.type)) {
        errors.push(`outcome_events[${index}].type is invalid`);
      }
      if (
        typeof event.at !== "string" ||
        !Number.isFinite(Date.parse(event.at))
      ) {
        errors.push(`outcome_events[${index}].at is invalid`);
      }
      for (const field of ["previous_outcome", "corrected_outcome"]) {
        if (
          event[field] !== undefined &&
          !["", "no_response", "replied", "interview", "offer", "rejected"].includes(
            event[field]
          )
        ) {
          errors.push(`outcome_events[${index}].${field} is invalid`);
        }
      }
    }
  }
  for (const field of schema?.timestamp_fields ?? []) {
    const value = record?.[field];
    if (value === "" || value === undefined || value === null) continue;
    if (typeof value !== "string" || !Number.isFinite(Date.parse(value))) {
      errors.push(`${field} must be a valid timestamp`);
    }
  }
  return errors;
}

function applyValidatedRecordUpdate(record, updates, schema) {
  const candidate = { ...record, ...updates };
  const errors = validateRecordContract(candidate, schema);
  if (errors.length > 0) {
    throw new Error(`Invalid record update: ${errors.join("; ")}`);
  }
  return candidate;
}

function validatePipelineSchema(schema) {
  const errors = [];
  if (schema?.schema_version !== 1) errors.push("schema_version must be 1");
  if (!Array.isArray(schema?.fields) || schema.fields.length === 0) errors.push("fields are required");
  if (!Array.isArray(schema?.pipeline_statuses) || schema.pipeline_statuses.length === 0) {
    errors.push("pipeline_statuses are required");
  }
  const duplicateFields = schema?.fields?.filter((field, index, all) => all.indexOf(field) !== index) ?? [];
  if (duplicateFields.length > 0) errors.push(`duplicate fields: ${[...new Set(duplicateFields)].join(", ")}`);
  const fields = new Set(schema?.fields ?? []);
  for (const collection of ["string_list_fields", "json_array_fields", "timestamp_fields"]) {
    if (!Array.isArray(schema?.[collection])) {
      errors.push(`${collection} must be an array`);
      continue;
    }
    for (const field of schema[collection]) {
      if (!fields.has(field)) errors.push(`${collection} references unknown field: ${field}`);
    }
  }
  for (const [field, rule] of Object.entries(schema?.field_rules ?? {})) {
    if (!fields.has(field)) errors.push(`field rule references unknown field: ${field}`);
    if (!["number", "integer", "enum", "string"].includes(rule?.type)) {
      errors.push(`field rule has unsupported type for ${field}`);
    }
    if (rule?.type === "enum" && (!Array.isArray(rule.values) || rule.values.length === 0)) {
      errors.push(`enum field rule requires values for ${field}`);
    }
    if (rule?.type === "string" && rule.pattern) {
      try {
        new RegExp(rule.pattern);
      } catch {
        errors.push(`string field rule has invalid pattern for ${field}`);
      }
    }
  }

  const statuses = new Set(schema?.pipeline_statuses ?? []);
  for (const [from, destinations] of Object.entries(schema?.transitions ?? {})) {
    if (!statuses.has(from)) errors.push(`transition source is not a status: ${from}`);
    for (const to of destinations) {
      if (!statuses.has(to)) errors.push(`transition destination is not a status: ${to}`);
    }
  }
  for (const status of statuses) {
    if (!(status in (schema?.transitions ?? {}))) errors.push(`missing transitions for status: ${status}`);
  }
  return errors;
}

function canTransition(schema, from, to) {
  return (schema.transitions?.[from] ?? []).includes(to);
}

function transitionRecord(record, to, schema, now = new Date().toISOString()) {
  const from = record.pipeline_status;
  if (!canTransition(schema, from, to)) {
    throw new Error(`Invalid pipeline transition: ${from} -> ${to}`);
  }
  const next = {
    ...record,
    pipeline_status: to,
    updated_at: now
  };
  return { ...next, state_guard: stateGuard(next) };
}

function isStaleClaim(record, nowMs, leaseMs) {
  if (!record.processing_token || !record.processing_started_at) return true;
  const startedAt = Date.parse(record.processing_started_at);
  return !Number.isFinite(startedAt) || nowMs - startedAt >= leaseMs;
}

function processingCommitGuard(token) {
  const value = String(token || "").trim();
  return value ? `commit:${value}` : "";
}

function claimRecord(record, { stage, token, now, leaseMs }) {
  const nowMs = Date.parse(now);
  if (!stage || !token || !Number.isFinite(nowMs) || !Number.isFinite(leaseMs) || leaseMs < 1) {
    throw new Error("stage, token, valid now, and positive leaseMs are required");
  }
  if (record.processing_token && !isStaleClaim(record, nowMs, leaseMs)) {
    return { claimed: false, record };
  }
  return {
    claimed: true,
    record: {
      ...record,
      processing_stage: stage,
      processing_token: token,
      processing_commit_guard: processingCommitGuard(token),
      processing_started_at: now,
      updated_at: now
    }
  };
}

function releaseClaim(record, token, now = new Date().toISOString()) {
  if (record.processing_token && record.processing_token !== token) {
    throw new Error("processing token mismatch");
  }
  const next = {
    ...record,
    processing_stage: "",
    processing_token: "",
    processing_started_at: "",
    updated_at: now
  };
  return { ...next, state_guard: stateGuard(next) };
}

function createProcessingClaim(record, executionId, now, leaseMs) {
  const token = `${executionId}:${record.canonical_job_id}:${record.work_stage}`;
  return {
    canonical_job_id: record.canonical_job_id,
    processing_stage: record.work_stage,
    processing_token: token,
    created_at: now,
    expires_at: new Date(Date.parse(now) + leaseMs).toISOString()
  };
}

function chooseWinningClaims(proposedRecords, allClaims, now = new Date().toISOString()) {
  const claimKey = (record) =>
    `${String(record?.canonical_job_id || "")
      .trim()
      .normalize("NFKC")
      .toLocaleLowerCase("en-US")}:${String(
      record?.processing_stage || record?.work_stage || ""
    ).trim()}`;
  const nowMs = Date.parse(now);
  const expectedLeaseMsByKey = new Map();
  for (const record of proposedRecords) {
    const claimCreatedAt = Date.parse(
      record?.claim_created_at ?? record?.created_at
    );
    const claimExpiresAt = Date.parse(
      record?.claim_expires_at ?? record?.expires_at
    );
    const leaseMs = claimExpiresAt - claimCreatedAt;
    if (Number.isFinite(leaseMs) && leaseMs > 0) {
      expectedLeaseMsByKey.set(claimKey(record), leaseMs);
    }
  }
  const rowNumberCounts = new Map();
  for (const claim of allClaims) {
    const rowNumber = Number(claim?.row_number);
    if (!Number.isInteger(rowNumber) || rowNumber < 2) continue;
    rowNumberCounts.set(
      rowNumber,
      (rowNumberCounts.get(rowNumber) || 0) + 1
    );
  }
  const validClaims = allClaims.filter((claim) => {
    const createdAt = Date.parse(claim.created_at);
    const expiresAt = Date.parse(claim.expires_at);
    const rowNumber = Number(claim.row_number);
    const expectedLeaseMs = expectedLeaseMsByKey.get(claimKey(claim));
    return (
      claim.canonical_job_id &&
      claim.processing_stage &&
      claim.processing_token &&
      Number.isFinite(createdAt) &&
      Number.isFinite(expiresAt) &&
      createdAt <= nowMs &&
      expiresAt > createdAt &&
      expiresAt > nowMs &&
      (!Number.isFinite(expectedLeaseMs) ||
        expiresAt - createdAt <= expectedLeaseMs) &&
      Number.isInteger(rowNumber) &&
      rowNumber >= 2 &&
      rowNumberCounts.get(rowNumber) === 1
    );
  });
  const winners = new Map();
  for (const claim of validClaims) {
    const key = claimKey(claim);
    const current = winners.get(key);
    const claimRow = Number(claim.row_number);
    if (!current || claimRow < Number(current.row_number)) {
      winners.set(key, claim);
    }
  }
  const emitted = new Set();
  return proposedRecords.filter((record) => {
    const key = claimKey(record);
    if (
      emitted.has(key) ||
      winners.get(key)?.processing_token !== record.processing_token
    ) {
      return false;
    }
    emitted.add(key);
    return true;
  });
}


const DAY_MINUTES = 24 * 60;
const DAY_HOURS = 24;

function integerInRange(value, minimum, maximum) {
  return (
    Number.isInteger(value) &&
    value >= minimum &&
    value <= maximum
  );
}

function validateMinuteIntervalSchedule(
  config,
  label = "interval schedule"
) {
  const errors = [];
  const intervalMinutes = config?.schedule_minutes;
  const offsetMinutes = config?.schedule_offset_minutes;
  if (
    !Number.isInteger(intervalMinutes) ||
    intervalMinutes < 1 ||
    intervalMinutes > DAY_MINUTES ||
    DAY_MINUTES % intervalMinutes !== 0
  ) {
    errors.push(
      `${label} schedule_minutes must be a positive divisor of ${DAY_MINUTES}`
    );
  }
  if (
    !Number.isInteger(offsetMinutes) ||
    offsetMinutes < 0 ||
    (Number.isInteger(intervalMinutes) && offsetMinutes >= intervalMinutes)
  ) {
    errors.push(
      `${label} schedule_offset_minutes must be from 0 through schedule_minutes - 1`
    );
  }
  return errors;
}

function minuteIntervalExecutionMinutes(
  config,
  label = "interval schedule"
) {
  const errors = validateMinuteIntervalSchedule(config, label);
  if (errors.length > 0) {
    throw new Error(`Invalid ${label}:\n- ${errors.join("\n- ")}`);
  }
  const minutes = [];
  for (
    let minute = config.schedule_offset_minutes;
    minute < DAY_MINUTES;
    minute += config.schedule_minutes
  ) {
    minutes.push(minute);
  }
  return minutes;
}

function minuteIntervalScheduleRules(
  config,
  label = "interval schedule"
) {
  const executionMinutes = minuteIntervalExecutionMinutes(config, label);
  const hoursByMinute = new Map();
  for (const executionMinute of executionMinutes) {
    const minute = executionMinute % 60;
    const hour = Math.floor(executionMinute / 60);
    if (!hoursByMinute.has(minute)) hoursByMinute.set(minute, []);
    hoursByMinute.get(minute).push(hour);
  }

  const minutesByHours = new Map();
  for (const [minute, hours] of hoursByMinute) {
    const key = hours.join(",");
    if (!minutesByHours.has(key)) {
      minutesByHours.set(key, { hours, minutes: [] });
    }
    minutesByHours.get(key).minutes.push(minute);
  }

  return [...minutesByHours.values()]
    .map(({ hours, minutes }) => ({
      firstExecutionMinute: Math.min(
        ...executionMinutes.filter(
          (executionMinute) =>
            minutes.includes(executionMinute % 60) &&
            hours.includes(Math.floor(executionMinute / 60))
        )
      ),
      rule: {
        field: "cronExpression",
        expression: `0 ${minutes
          .sort((left, right) => left - right)
          .join(",")} ${
          hours.length === DAY_HOURS ? "*" : hours.join(",")
        } * * *`
      }
    }))
    .sort(
      (left, right) =>
        left.firstExecutionMinute - right.firstExecutionMinute
    )
    .map(({ rule }) => rule);
}

function localMinute(schedule) {
  return schedule.trigger_at_hour * 60 + schedule.trigger_at_minute;
}

function validateAnalyticsSchedule(policy) {
  const schedule = policy?.schedule;
  const errors = [];
  if (!schedule || typeof schedule !== "object" || Array.isArray(schedule)) {
    return ["analytics schedule must be an object"];
  }
  if (schedule.field !== "days") {
    errors.push("analytics schedule field must be days");
  }
  if (schedule.days_interval !== 1 || policy.schedule_hours !== 24) {
    errors.push("analytics schedule must run once every 24 hours");
  }
  if (!integerInRange(schedule.trigger_at_hour, 0, 23)) {
    errors.push("analytics trigger_at_hour must be from 0 through 23");
  }
  if (!integerInRange(schedule.trigger_at_minute, 0, 59)) {
    errors.push("analytics trigger_at_minute must be from 0 through 59");
  }
  return errors;
}

function validateRecommendationSchedule(policy) {
  const schedule = policy?.schedule;
  const errors = [];
  if (!schedule || typeof schedule !== "object" || Array.isArray(schedule)) {
    return ["recommendation schedule must be an object"];
  }
  if (schedule.field !== "weeks") {
    errors.push("recommendation schedule field must be weeks");
  }
  if (schedule.weeks_interval !== 1 || policy.schedule_hours !== 168) {
    errors.push("recommendation schedule must run once every 168 hours");
  }
  if (
    !Array.isArray(schedule.trigger_at_days) ||
    schedule.trigger_at_days.length !== 1 ||
    !integerInRange(schedule.trigger_at_days[0], 0, 6)
  ) {
    errors.push(
      "recommendation trigger_at_days must contain one weekday from 0 through 6"
    );
  }
  if (!integerInRange(schedule.trigger_at_hour, 0, 23)) {
    errors.push("recommendation trigger_at_hour must be from 0 through 23");
  }
  if (!integerInRange(schedule.trigger_at_minute, 0, 59)) {
    errors.push("recommendation trigger_at_minute must be from 0 through 59");
  }
  if (
    !Number.isInteger(policy.source_completion_buffer_minutes) ||
    policy.source_completion_buffer_minutes < 1
  ) {
    errors.push(
      "source_completion_buffer_minutes must be a positive integer"
    );
  }
  return errors;
}

function learningScheduleTiming(analyticsPolicy, recommendationPolicy) {
  const errors = [
    ...validateAnalyticsSchedule(analyticsPolicy),
    ...validateRecommendationSchedule(recommendationPolicy)
  ];
  if (errors.length > 0) {
    throw new Error(`Invalid learning schedule:\n- ${errors.join("\n- ")}`);
  }
  const analyticsStartMinute = localMinute(analyticsPolicy.schedule);
  const analyticsDeadlineMinute =
    analyticsStartMinute +
    Math.ceil(analyticsPolicy.execution_timeout_seconds / 60);
  const recommendationStartMinute = localMinute(
    recommendationPolicy.schedule
  );
  return {
    analytics_start_minute: analyticsStartMinute,
    analytics_deadline_minute: analyticsDeadlineMinute,
    recommendation_start_minute: recommendationStartMinute,
    completion_buffer_minutes:
      recommendationStartMinute - analyticsDeadlineMinute,
    day_minutes: DAY_MINUTES
  };
}

function validateLearningSchedulePair(
  analyticsPolicy,
  recommendationPolicy
) {
  const errors = [
    ...validateAnalyticsSchedule(analyticsPolicy),
    ...validateRecommendationSchedule(recommendationPolicy)
  ];
  if (errors.length > 0) return errors;
  const timing = learningScheduleTiming(
    analyticsPolicy,
    recommendationPolicy
  );
  if (
    timing.analytics_deadline_minute >= DAY_MINUTES ||
    timing.completion_buffer_minutes <
      recommendationPolicy.source_completion_buffer_minutes
  ) {
    errors.push(
      "recommendation schedule must start after the analytics timeout and completion buffer"
    );
  }
  return errors;
}

function analyticsScheduleRule(policy) {
  const errors = validateAnalyticsSchedule(policy);
  if (errors.length > 0) {
    throw new Error(`Invalid analytics schedule:\n- ${errors.join("\n- ")}`);
  }
  return {
    field: "days",
    daysInterval: policy.schedule.days_interval,
    triggerAtHour: policy.schedule.trigger_at_hour,
    triggerAtMinute: policy.schedule.trigger_at_minute
  };
}

function recommendationScheduleRule(analyticsPolicy, policy) {
  const errors = validateLearningSchedulePair(analyticsPolicy, policy);
  if (errors.length > 0) {
    throw new Error(`Invalid learning schedule:\n- ${errors.join("\n- ")}`);
  }
  return {
    field: "weeks",
    weeksInterval: policy.schedule.weeks_interval,
    triggerAtDay: [...policy.schedule.trigger_at_days],
    triggerAtHour: policy.schedule.trigger_at_hour,
    triggerAtMinute: policy.schedule.trigger_at_minute
  };
}


const DAY_MS = 86_400_000;
const OUTCOME_METRICS = {
  replied: "reply_rate",
  interview: "interview_rate",
  offer: "offer_rate",
  rejected: "rejection_rate",
  no_response: "no_response_rate"
};
const IMMUTABLE_APPLICATION_FIELDS = [
  "application_qualification_score",
  "application_opportunity_score",
  "application_ranking_confidence",
  "application_scoring_policy_version",
  "application_apply_points_recommendation",
  "application_pack_status_at_apply",
  "application_posting_age_days",
  "application_message_strategy",
  "apply_points_used",
  "application_snapshot_at",
  "application_decided_at"
];

function hasValue(value) {
  return value !== undefined && value !== null && value !== "";
}

function canonicalIdentityKey(value) {
  return String(value || "")
    .trim()
    .normalize("NFKC")
    .toLocaleLowerCase("en-US");
}

function timestamp(value) {
  const parsed = Date.parse(value || "");
  return Number.isFinite(parsed) ? parsed : undefined;
}

function safeNumber(value) {
  return typeof value === "number" && Number.isFinite(value)
    ? value
    : undefined;
}

function validContractValue(value, rule) {
  if (!rule || value === "" || value === undefined || value === null) {
    return false;
  }
  if (rule.type === "enum") return rule.values?.includes(value) === true;
  if (rule.type === "string") {
    return (
      typeof value === "string" &&
      (rule.maximum_length === undefined ||
        value.length <= rule.maximum_length) &&
      (!rule.pattern || new RegExp(rule.pattern).test(value))
    );
  }
  if (typeof value !== "number" || !Number.isFinite(value)) return false;
  if (rule.type === "integer" && !Number.isInteger(value)) return false;
  if (rule.minimum !== undefined && value < rule.minimum) return false;
  if (rule.maximum !== undefined && value > rule.maximum) return false;
  return true;
}

function safeDivide(numerator, denominator, multiplier = 1) {
  return denominator > 0
    ? Math.round((numerator / denominator) * multiplier * 1_000_000) / 1_000_000
    : "";
}

function safeSheetText(value, maximum = 500) {
  const normalized = String(value || "")
    .normalize("NFKC")
    .replace(/[\u200b-\u200d\u2060\ufeff]/gi, "")
    .replace(/[\u0000-\u001f\u007f-\u009f]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, maximum);
  return /^[=+\-@]/.test(normalized) ? `'${normalized}` : normalized;
}

function uniqueStrings(...values) {
  return [
    ...new Set(
      values
        .flat()
        .map((value) => String(value || "").trim())
        .filter(Boolean)
    )
  ].sort((left, right) => left.localeCompare(right));
}

function uniqueObjects(values, keyFor) {
  const result = new Map();
  for (const value of values.flat()) {
    if (!value || typeof value !== "object" || Array.isArray(value)) continue;
    const key = keyFor(value);
    if (!key || result.has(key)) continue;
    result.set(key, value);
  }
  return [...result.values()];
}

function rotateRight(value, amount) {
  return (value >>> amount) | (value << (32 - amount));
}

function stableSha256(value) {
  const bytes = new TextEncoder().encode(String(value));
  const paddedLength = Math.ceil((bytes.length + 9) / 64) * 64;
  const padded = new Uint8Array(paddedLength);
  padded.set(bytes);
  padded[bytes.length] = 0x80;
  const bitLength = bytes.length * 8;
  const lengthView = new DataView(padded.buffer);
  lengthView.setUint32(paddedLength - 8, Math.floor(bitLength / 0x100000000));
  lengthView.setUint32(paddedLength - 4, bitLength >>> 0);

  const constants = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5,
    0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
    0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc,
    0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
    0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
    0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3,
    0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5,
    0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
    0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
  ];
  const state = new Uint32Array([
    0x6a09e667,
    0xbb67ae85,
    0x3c6ef372,
    0xa54ff53a,
    0x510e527f,
    0x9b05688c,
    0x1f83d9ab,
    0x5be0cd19
  ]);
  const words = new Uint32Array(64);

  for (let offset = 0; offset < padded.length; offset += 64) {
    for (let index = 0; index < 16; index += 1) {
      words[index] = lengthView.getUint32(offset + index * 4);
    }
    for (let index = 16; index < 64; index += 1) {
      const previous15 = words[index - 15];
      const previous2 = words[index - 2];
      const sigma0 =
        rotateRight(previous15, 7) ^
        rotateRight(previous15, 18) ^
        (previous15 >>> 3);
      const sigma1 =
        rotateRight(previous2, 17) ^
        rotateRight(previous2, 19) ^
        (previous2 >>> 10);
      words[index] =
        (words[index - 16] + sigma0 + words[index - 7] + sigma1) >>> 0;
    }

    let [a, b, c, d, e, f, g, h] = state;
    for (let index = 0; index < 64; index += 1) {
      const sum1 =
        rotateRight(e, 6) ^ rotateRight(e, 11) ^ rotateRight(e, 25);
      const choice = (e & f) ^ (~e & g);
      const temporary1 =
        (h + sum1 + choice + constants[index] + words[index]) >>> 0;
      const sum0 =
        rotateRight(a, 2) ^ rotateRight(a, 13) ^ rotateRight(a, 22);
      const majority = (a & b) ^ (a & c) ^ (b & c);
      const temporary2 = (sum0 + majority) >>> 0;
      h = g;
      g = f;
      f = e;
      e = (d + temporary1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (temporary1 + temporary2) >>> 0;
    }
    state[0] = (state[0] + a) >>> 0;
    state[1] = (state[1] + b) >>> 0;
    state[2] = (state[2] + c) >>> 0;
    state[3] = (state[3] + d) >>> 0;
    state[4] = (state[4] + e) >>> 0;
    state[5] = (state[5] + f) >>> 0;
    state[6] = (state[6] + g) >>> 0;
    state[7] = (state[7] + h) >>> 0;
  }
  return [...state]
    .map((word) => word.toString(16).padStart(8, "0"))
    .join("");
}

function reportId(policy, resultKey) {
  const version = policy.metric_definition_version.replace(/[^a-z0-9]+/gi, "-");
  return `analytics-${version}-${resultKey}`;
}

function validateBands(bands, maximum, name) {
  if (
    !Array.isArray(bands) ||
    bands.length === 0 ||
    bands.some(
      (band) =>
        !/^[a-z0-9_]+$/.test(band?.key ?? "") ||
        typeof band?.label !== "string" ||
        !Number.isFinite(band?.maximum)
    )
  ) {
    return [`${name} are invalid`];
  }
  const errors = [];
  for (let index = 0; index < bands.length; index += 1) {
    if (index > 0 && bands[index].maximum <= bands[index - 1].maximum) {
      errors.push(`${name} must be ordered by increasing maximum`);
      break;
    }
  }
  if (bands.at(-1).maximum < maximum) {
    errors.push(`${name} do not cover the supported maximum`);
  }
  return errors;
}

function validateAnalyticsPolicy(policy) {
  const errors = [];
  if (!policy || typeof policy !== "object" || Array.isArray(policy)) {
    return ["analytics policy must be an object"];
  }
  if (policy.schema_version !== 1) {
    errors.push("analytics policy schema_version must be 1");
  }
  for (const field of ["metric_definition_version", "band_version"]) {
    if (!/^\d{4}-\d{2}-\d{2}\/v\d+$/.test(policy[field] ?? "")) {
      errors.push(`${field} must use YYYY-MM-DD/vN`);
    }
  }
  if (!Number.isInteger(policy.schedule_hours) || policy.schedule_hours < 1) {
    errors.push("schedule_hours must be a positive integer");
  }
  errors.push(...validateAnalyticsSchedule(policy));
  if (
    !Number.isInteger(policy.execution_timeout_seconds) ||
    policy.execution_timeout_seconds < 1
  ) {
    errors.push("execution_timeout_seconds must be a positive integer");
  } else if (
    Number.isInteger(policy.schedule_hours) &&
    policy.execution_timeout_seconds >= policy.schedule_hours * 60 * 60
  ) {
    errors.push("execution timeout must be shorter than the analytics schedule");
  }
  try {
    new Intl.DateTimeFormat("en-CA", {
      timeZone: policy.analysis_timezone
    }).format(new Date());
  } catch {
    errors.push("analysis_timezone must be a supported IANA timezone");
  }
  if (policy.analysis_window?.type !== "all_time") {
    errors.push("only the explicit all_time analysis window is supported");
  }
  if (policy.attribution?.policy !== "multi_touch_full_credit") {
    errors.push("attribution policy must be multi_touch_full_credit");
  }
  const expectedNonAdditive = [
    "matched_skill",
    "requirement_gap",
    "role_family",
    "search_query"
  ];
  if (
    JSON.stringify(
      [...(policy.attribution?.non_additive_dimensions ?? [])].sort()
    ) !== JSON.stringify(expectedNonAdditive)
  ) {
    errors.push("non-additive dimensions are incomplete");
  }
  if (
    !Number.isFinite(
      policy.top_ranked?.minimum_application_opportunity_score
    ) ||
    policy.top_ranked.minimum_application_opportunity_score < 0 ||
    policy.top_ranked.minimum_application_opportunity_score > 100
  ) {
    errors.push("top-ranked threshold must be between 0 and 100");
  }
  errors.push(...validateBands(policy.score_bands, 100, "score_bands"));
  errors.push(
    ...validateBands(policy.posting_age_bands, 36500, "posting_age_bands")
  );
  errors.push(
    ...validateBands(policy.salary?.bands, 1_000_000_000, "salary.bands")
  );
  if (
    policy.salary?.currency !== "PHP" ||
    policy.salary?.period !== "month"
  ) {
    errors.push("analytics supports only PHP monthly salary bands");
  }
  const expectedDimensions = [
    "search_query",
    "role_family",
    "qualification_score_band",
    "opportunity_score_band",
    "confidence",
    "matched_skill",
    "requirement_gap",
    "salary_band",
    "posting_age_band",
    "apply_points_used",
    "apply_points_recommendation",
    "message_strategy",
    "instruction_completeness",
    "rank_cohort"
  ];
  if (
    JSON.stringify(policy.dimension_order) !==
    JSON.stringify(expectedDimensions)
  ) {
    errors.push("dimension_order must define every supported dimension once");
  }
  if (
    JSON.stringify(policy.outcomes) !==
    JSON.stringify(["replied", "interview", "offer", "rejected", "no_response"])
  ) {
    errors.push("outcomes must define every explicit supported outcome once");
  }
  for (const [field, expected] of [
    ["detail_fields", 23],
    ["report_fields", 14]
  ]) {
    if (
      !Array.isArray(policy[field]) ||
      policy[field].length !== expected ||
      new Set(policy[field]).size !== policy[field].length
    ) {
      errors.push(`${field} are invalid`);
    }
  }
  for (const field of ["detail_sheet", "reports_sheet"]) {
    if (!String(policy[field] || "").trim()) errors.push(`${field} is required`);
  }
  return errors;
}

function mergeAnalyticsRecords(current, incoming, diagnostics) {
  if (!current) return incoming;
  diagnostics.overlap_records += 1;
  const currentUpdated = timestamp(current.updated_at) ?? Number.NEGATIVE_INFINITY;
  const incomingUpdated = timestamp(incoming.updated_at) ?? Number.NEGATIVE_INFINITY;
  const newer = incomingUpdated >= currentUpdated ? incoming : current;
  const older = newer === incoming ? current : incoming;
  const merged = { ...older };
  for (const [field, value] of Object.entries(newer)) {
    if (hasValue(value)) merged[field] = value;
  }
  merged.search_queries = uniqueStrings(
    current.search_queries,
    incoming.search_queries
  );
  merged.role_families = uniqueStrings(
    current.role_families,
    incoming.role_families
  );
  merged.match_reasons = uniqueStrings(
    current.match_reasons,
    incoming.match_reasons
  );
  merged.requirement_gaps = uniqueStrings(
    current.requirement_gaps,
    incoming.requirement_gaps
  );
  merged.outcome_events = mergeOutcomeEvents(
    current.outcome_events,
    incoming.outcome_events
  );
  merged.requirement_gap_details = uniqueObjects(
    [current.requirement_gap_details, incoming.requirement_gap_details],
    (gap) =>
      `${String(gap.classification || "unknown").trim()}\u001f${String(gap.requirement || "").trim().toLowerCase()}`
  );
  merged.application_warnings = uniqueObjects(
    [current.application_warnings, incoming.application_warnings],
    (warning) =>
      [
        warning.code,
        warning.category,
        warning.instruction_id,
        warning.question_id
      ]
        .map((value) => String(value || "").trim())
        .join("\u001f")
  );
  merged.__analytics_malformed_requirement_gap_details =
    current.__analytics_malformed_requirement_gap_details === true ||
    incoming.__analytics_malformed_requirement_gap_details === true;
  merged.__analytics_malformed_application_warnings =
    current.__analytics_malformed_application_warnings === true ||
    incoming.__analytics_malformed_application_warnings === true;

  const currentOutcomeAt = timestamp(current.outcome_at);
  const incomingOutcomeAt = timestamp(incoming.outcome_at);
  if (
    currentOutcomeAt !== undefined &&
    (incomingOutcomeAt === undefined || currentOutcomeAt > incomingOutcomeAt)
  ) {
    merged.outcome = current.outcome;
    merged.outcome_at = current.outcome_at;
  } else if (incomingOutcomeAt !== undefined) {
    merged.outcome = incoming.outcome;
    merged.outcome_at = incoming.outcome_at;
  }

  const snapshotCandidates = [current, incoming]
    .filter((record) => timestamp(record.application_snapshot_at) !== undefined)
    .sort(
      (left, right) =>
        timestamp(left.application_snapshot_at) -
        timestamp(right.application_snapshot_at)
    );
  if (snapshotCandidates.length > 0) {
    const canonicalSnapshot = snapshotCandidates[0];
    for (const field of IMMUTABLE_APPLICATION_FIELDS) {
      merged[field] =
        snapshotCandidates.find((record) => hasValue(record[field]))?.[field] ??
        canonicalSnapshot[field] ??
        "";
    }
    if (
      snapshotCandidates.length > 1 &&
      IMMUTABLE_APPLICATION_FIELDS.some(
        (field) =>
          hasValue(snapshotCandidates[0][field]) &&
          hasValue(snapshotCandidates[1][field]) &&
          String(snapshotCandidates[0][field]) !==
            String(snapshotCandidates[1][field])
      )
    ) {
      diagnostics.application_snapshot_conflicts += 1;
    }
  }

  const decisions = uniqueStrings(
    current.application_decision,
    incoming.application_decision
  );
  if (decisions.length > 1) {
    diagnostics.application_decision_conflicts += 1;
    const decisionSource = [current, incoming]
      .filter((record) => record.application_decision)
      .sort(
        (left, right) =>
          (timestamp(right.application_decided_at) ??
            timestamp(right.updated_at) ??
            Number.NEGATIVE_INFINITY) -
          (timestamp(left.application_decided_at) ??
            timestamp(left.updated_at) ??
            Number.NEGATIVE_INFINITY)
      )[0];
    merged.application_decision = decisionSource.application_decision;
  }
  return merged;
}

function deduplicateAnalyticsRecords(
  activeRows,
  archiveRows,
  schema,
  now = new Date().toISOString()
) {
  const records = new Map();
  const diagnostics = {
    input_rows: activeRows.length + archiveRows.length,
    invalid_identity_rows: 0,
    overlap_records: 0,
    application_snapshot_conflicts: 0,
    application_decision_conflicts: 0,
    malformed_outcome_history_rows: 0,
    malformed_requirement_gap_rows: 0,
    malformed_application_warning_rows: 0
  };
  for (const raw of [...activeRows, ...archiveRows]) {
    const normalized = normalizeLegacyRecord(raw, schema, now);
    if (!Array.isArray(normalized.outcome_events)) {
      diagnostics.malformed_outcome_history_rows += 1;
    }
    if (!Array.isArray(normalized.requirement_gap_details)) {
      diagnostics.malformed_requirement_gap_rows += 1;
      normalized.__analytics_malformed_requirement_gap_details = true;
    }
    if (!Array.isArray(normalized.application_warnings)) {
      diagnostics.malformed_application_warning_rows += 1;
      normalized.__analytics_malformed_application_warnings = true;
    }
    const identityKey = canonicalIdentityKey(normalized.canonical_job_id);
    if (!identityKey) {
      diagnostics.invalid_identity_rows += 1;
      continue;
    }
    const merged = mergeAnalyticsRecords(
      records.get(identityKey),
      normalized,
      diagnostics
    );
    records.set(
      identityKey,
      {
        ...merged,
        canonical_job_id: identityKey
      }
    );
  }
  return {
    records: [...records.values()].sort((left, right) =>
      left.canonical_job_id.localeCompare(right.canonical_job_id)
    ),
    diagnostics
  };
}

function isApplied(record) {
  return (
    record.application_decision === "applied" ||
    (record.pipeline_status === "archived" &&
      record.archived_from_status === "applied")
  );
}

function outcomeSet(record) {
  const outcomes = new Set();
  for (const event of Array.isArray(record.outcome_events)
    ? record.outcome_events
    : []) {
    if (OUTCOME_METRICS[event?.type]) outcomes.add(event.type);
  }
  if (OUTCOME_METRICS[record.outcome]) outcomes.add(record.outcome);
  return outcomes;
}

function bandFor(value, bands) {
  const numeric = safeNumber(value);
  if (numeric === undefined || numeric < 0) {
    return { key: "unknown", label: "Unknown", known: false };
  }
  const band = bands.find((candidate) => numeric <= candidate.maximum);
  return band
    ? { key: band.key, label: band.label, known: true }
    : { key: "unknown", label: "Unknown", known: false };
}

function parseMonthlyPhpSalary(value) {
  const text = String(value || "").normalize("NFKC").slice(0, 2000);
  if (
    !text ||
    !/(?:PHP|₱)/i.test(text) ||
    !/(?:\/\s*month|per month|monthly)/i.test(text) ||
    /\b(?:USD|EUR|GBP|AUD|CAD)\b|US\$/i.test(text)
  ) {
    return undefined;
  }
  const match = text.match(
    /(?:PHP|₱)\s*([\d,.]+)(?:\s*(?:-|to)\s*(?:PHP|₱)?\s*([\d,.]+))?/i
  );
  const amounts = [match?.[1], match?.[2]]
    .filter(Boolean)
    .map((part) => Number(part.replace(/,/g, "")))
    .filter((part) => Number.isFinite(part) && part >= 0);
  return amounts.length > 0
    ? amounts.reduce((sum, amount) => sum + amount, 0) / amounts.length
    : undefined;
}

function matchedSkills(record) {
  const values = (Array.isArray(record.match_reasons)
    ? record.match_reasons
    : []
  )
    .map((reason) => String(reason).match(/^Matched skill:\s*(.+)$/i)?.[1])
    .filter(Boolean);
  if (values.length > 0) return uniqueStrings(values);
  return record.evaluated_at || record.scoring_policy_version ? ["none"] : [];
}

function requirementGaps(record) {
  const structured = Array.isArray(record.requirement_gap_details)
    ? record.requirement_gap_details
        .filter((gap) => gap?.requirement)
        .map(
          (gap) =>
            `${gap.classification || "unknown"}:${String(gap.requirement).trim()}`
        )
    : [];
  if (structured.length > 0) return uniqueStrings(structured);
  const legacy = Array.isArray(record.requirement_gaps)
    ? record.requirement_gaps
    : [];
  if (legacy.length > 0) {
    return uniqueStrings(legacy.map((gap) => `unknown:${gap}`));
  }
  return record.evaluated_at || record.scoring_policy_version ? ["none"] : [];
}

function dimensionValues(record, dimension, policy, schema) {
  if (dimension === "search_query") {
    return uniqueStrings(record.search_queries).map((value) => ({
      key: value,
      label: value,
      known: true
    }));
  }
  if (dimension === "role_family") {
    return uniqueStrings(record.role_families).map((value) => ({
      key: value,
      label: value,
      known: true
    }));
  }
  if (dimension === "qualification_score_band") {
    return [
      bandFor(
        validContractValue(
          record.application_qualification_score,
          schema.field_rules?.application_qualification_score
        )
          ? record.application_qualification_score
          : undefined,
        policy.score_bands
      )
    ];
  }
  if (dimension === "opportunity_score_band") {
    return [
      bandFor(
        validContractValue(
          record.application_opportunity_score,
          schema.field_rules?.application_opportunity_score
        )
          ? record.application_opportunity_score
          : undefined,
        policy.score_bands
      )
    ];
  }
  if (dimension === "confidence") {
    const value = validContractValue(
      record.application_ranking_confidence,
      schema.field_rules?.application_ranking_confidence
    )
      ? record.application_ranking_confidence
      : "";
    return [
      value
        ? { key: value, label: value, known: true }
        : { key: "unknown", label: "Unknown", known: false }
    ];
  }
  if (dimension === "matched_skill") {
    return matchedSkills(record).map((value) => ({
      key: value,
      label: value === "none" ? "No matched skill" : value,
      known: true
    }));
  }
  if (dimension === "requirement_gap") {
    return requirementGaps(record).map((value) => ({
      key: value,
      label: value === "none" ? "No requirement gap" : value,
      known: true
    }));
  }
  if (dimension === "salary_band") {
    return [
      bandFor(
        parseMonthlyPhpSalary(record.salary_text),
        policy.salary.bands
      )
    ];
  }
  if (dimension === "posting_age_band") {
    return [
      bandFor(
        validContractValue(
          record.application_posting_age_days,
          schema.field_rules?.application_posting_age_days
        )
          ? record.application_posting_age_days
          : undefined,
        policy.posting_age_bands
      )
    ];
  }
  if (dimension === "apply_points_used") {
    const points = safeNumber(record.apply_points_used);
    return [
      points !== undefined &&
      validContractValue(points, schema.field_rules?.apply_points_used)
        ? { key: String(points), label: `${points} points`, known: true }
        : { key: "unknown", label: "Unknown", known: false }
    ];
  }
  if (dimension === "apply_points_recommendation") {
    const value = validContractValue(
      record.application_apply_points_recommendation,
      schema.field_rules?.application_apply_points_recommendation
    )
      ? record.application_apply_points_recommendation
      : "";
    return [
      value
        ? { key: value, label: value, known: true }
        : { key: "unknown", label: "Unknown", known: false }
    ];
  }
  if (dimension === "message_strategy") {
    const value = validContractValue(
      record.application_message_strategy,
      schema.field_rules?.application_message_strategy
    )
      ? record.application_message_strategy
      : "";
    return [
      value
        ? { key: value, label: value, known: true }
        : { key: "unknown", label: "Unknown", known: false }
    ];
  }
  if (dimension === "instruction_completeness") {
    const status = validContractValue(
      record.application_pack_status_at_apply,
      schema.field_rules?.application_pack_status_at_apply
    )
      ? record.application_pack_status_at_apply
      : "";
    return [
      status === "ready"
        ? { key: "complete", label: "Instruction complete", known: true }
        : ["review_required", "blocked"].includes(status)
          ? { key: "incomplete", label: "Instruction incomplete", known: true }
          : { key: "unknown", label: "Unknown", known: false }
    ];
  }
  if (dimension === "rank_cohort") {
    const score = validContractValue(
      record.application_opportunity_score,
      schema.field_rules?.application_opportunity_score
    )
      ? record.application_opportunity_score
      : undefined;
    return [
      score === undefined
        ? { key: "unknown", label: "Unknown", known: false }
        : score >= policy.top_ranked.minimum_application_opportunity_score
          ? { key: "top_ranked", label: "Top-ranked", known: true }
          : { key: "lower_ranked", label: "Lower-ranked", known: true }
    ];
  }
  return [];
}

function dayKey(value, timeZone) {
  const parsed = timestamp(value);
  if (parsed === undefined) return undefined;
  return new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  }).format(new Date(parsed));
}

function baseRow(metadata, values = {}) {
  return {
    report_id: metadata.report_id,
    metric_definition_version: metadata.metric_definition_version,
    band_version: metadata.band_version,
    generated_at: metadata.generated_at,
    window_type: metadata.window_type,
    window_start_at: metadata.window_start_at,
    window_end_at: metadata.window_end_at,
    section: safeSheetText(values.section || "overall", 100),
    dimension: safeSheetText(values.dimension || "overall", 100),
    segment_key: safeSheetText(values.segment_key || "all"),
    segment_label: safeSheetText(
      values.segment_label || "All applications"
    ),
    metric_key: safeSheetText(values.metric_key || "", 120),
    numerator: values.numerator ?? "",
    denominator: values.denominator ?? "",
    value: values.value ?? "",
    unit: safeSheetText(values.unit || "count", 80),
    sample_size: values.sample_size ?? "",
    coverage_numerator: values.coverage_numerator ?? "",
    coverage_denominator: values.coverage_denominator ?? "",
    attribution: safeSheetText(values.attribution || "deduplicated", 120),
    non_additive: values.non_additive === true,
    note: safeSheetText(values.note || "", 1000)
  };
}

function conversionRows(metadata, cohort, values, policy) {
  const outcomes = new Map(
    policy.outcomes.map((outcome) => [
      outcome,
      cohort.filter((record) => outcomeSet(record).has(outcome)).length
    ])
  );
  const rows = [
    baseRow(metadata, {
      ...values,
      metric_key: "application_count",
      numerator: cohort.length,
      denominator: cohort.length,
      value: cohort.length,
      sample_size: cohort.length
    })
  ];
  for (const outcome of policy.outcomes) {
    const numerator = outcomes.get(outcome);
    rows.push(
      baseRow(metadata, {
        ...values,
        metric_key: OUTCOME_METRICS[outcome],
        numerator,
        denominator: cohort.length,
        value: safeDivide(numerator, cohort.length),
        unit: "rate",
        sample_size: cohort.length
      })
    );
  }
  return rows;
}

function dimensionsReport(metadata, applications, policy, schema) {
  const rows = [];
  for (const dimension of policy.dimension_order) {
    const segments = new Map();
    let knownApplications = 0;
    for (const application of applications) {
      let values = dimensionValues(application, dimension, policy, schema);
      if (values.length === 0) {
        values = [{ key: "unknown", label: "Unknown", known: false }];
      }
      if (values.some((value) => value.known)) knownApplications += 1;
      for (const value of values) {
        if (!segments.has(value.key)) {
          segments.set(value.key, { label: value.label, records: [] });
        }
        segments.get(value.key).records.push(application);
      }
    }
    const nonAdditive =
      policy.attribution.non_additive_dimensions.includes(dimension);
    const section = [
      "qualification_score_band",
      "opportunity_score_band"
    ].includes(dimension)
      ? "calibration"
      : ["instruction_completeness", "rank_cohort"].includes(dimension)
        ? "comparison"
        : "conversion";
    rows.push(
      baseRow(metadata, {
        section: "coverage",
        dimension,
        segment_key: "all",
        segment_label: "Known dimension coverage",
        metric_key: "known_application_coverage",
        numerator: knownApplications,
        denominator: applications.length,
        value: safeDivide(knownApplications, applications.length),
        unit: "rate",
        sample_size: applications.length,
        coverage_numerator: knownApplications,
        coverage_denominator: applications.length,
        attribution: nonAdditive
          ? policy.attribution.policy
          : "exclusive",
        non_additive: nonAdditive,
        note: nonAdditive
          ? "Multi-touch full-credit segment totals are non-additive; overall totals count each canonical application once."
          : ""
      })
    );
    for (const [key, segment] of [...segments.entries()].sort(
      ([left], [right]) =>
        (left === "unknown") - (right === "unknown") ||
        left.localeCompare(right)
    )) {
      rows.push(
        ...conversionRows(
          metadata,
          segment.records,
          {
            section,
            dimension,
            segment_key: key,
            segment_label: segment.label,
            attribution: nonAdditive
              ? policy.attribution.policy
              : "exclusive",
            non_additive: nonAdditive,
            note: nonAdditive
              ? "Non-additive multi-touch attribution."
              : ""
          },
          policy
        )
      );
    }
  }
  return rows;
}

function discoveryAndSkillDemandRows(metadata, records, policy) {
  const rows = [];
  for (const [dimension, field] of [
    ["search_query", "search_queries"],
    ["role_family", "role_families"]
  ]) {
    const segments = new Map();
    for (const record of records) {
      const values = uniqueStrings(record[field]);
      for (const value of values.length > 0 ? values : ["unknown"]) {
        if (!segments.has(value)) segments.set(value, new Set());
        segments.get(value).add(record.canonical_job_id);
      }
    }
    for (const [key, identities] of [...segments.entries()].sort(
      ([left], [right]) =>
        (left === "unknown") - (right === "unknown") ||
        left.localeCompare(right)
    )) {
      rows.push(
        baseRow(metadata, {
          section: "discovery_volume",
          dimension,
          segment_key: key,
          segment_label: key === "unknown" ? "Unknown" : key,
          metric_key: "discovered_job_count",
          numerator: identities.size,
          denominator: records.length,
          value: identities.size,
          unit: "count",
          sample_size: records.length,
          attribution: policy.attribution.policy,
          non_additive: true,
          note:
            "Multi-touch discovery volume is non-additive and is not conversion evidence by itself."
        })
      );
    }
  }

  const promising = records.filter(
    (record) =>
      safeNumber(record.opportunity_score) !== undefined &&
      record.opportunity_score >=
        policy.top_ranked.minimum_application_opportunity_score
  );
  const requests = new Map();
  let evaluatedPromising = 0;
  for (const record of promising) {
    const gapDetails = Array.isArray(record.requirement_gap_details)
      ? record.requirement_gap_details
      : undefined;
    if (
      !record.__analytics_malformed_requirement_gap_details &&
      (record.evaluated_at ||
        record.scoring_policy_version ||
        gapDetails?.length > 0)
    ) {
      evaluatedPromising += 1;
    }
    const requirements = uniqueStrings(
      (gapDetails || [])
        .filter((gap) => gap?.requirement)
        .map((gap) => String(gap.requirement).trim())
    );
    for (const requirement of requirements) {
      if (!requests.has(requirement)) requests.set(requirement, new Set());
      requests.get(requirement).add(record.canonical_job_id);
    }
  }
  rows.push(
    baseRow(metadata, {
      section: "coverage",
      dimension: "missing_requirement",
      segment_key: "all",
      segment_label: "Promising-job gap coverage",
      metric_key: "promising_job_gap_coverage",
      numerator: evaluatedPromising,
      denominator: promising.length,
      value: safeDivide(evaluatedPromising, promising.length),
      unit: "rate",
      sample_size: promising.length,
      coverage_numerator: evaluatedPromising,
      coverage_denominator: promising.length,
      attribution: "deduplicated",
      note:
        "Promising means current opportunity score at or above the configured top-ranked threshold."
    })
  );
  for (const [requirement, identities] of [...requests.entries()].sort(
    ([left], [right]) => left.localeCompare(right)
  )) {
    rows.push(
      baseRow(metadata, {
        section: "skill_demand",
        dimension: "missing_requirement",
        segment_key: requirement,
        segment_label: requirement,
        metric_key: "promising_job_request_count",
        numerator: identities.size,
        denominator: promising.length,
        value: identities.size,
        unit: "count",
        sample_size: promising.length,
        coverage_numerator: evaluatedPromising,
        coverage_denominator: promising.length,
        attribution: "deduplicated",
        note:
          "The deterministic ranker classified this requirement as unsupported by approved profile evidence; this row does not add a skill claim."
      })
    );
  }
  return rows;
}

function meanAndMedian(values) {
  if (values.length === 0) return { mean: "", median: "" };
  const sorted = [...values].sort((left, right) => left - right);
  const middle = Math.floor(sorted.length / 2);
  const median =
    sorted.length % 2 === 0
      ? (sorted[middle - 1] + sorted[middle]) / 2
      : sorted[middle];
  return {
    mean:
      Math.round(
        (values.reduce((sum, value) => sum + value, 0) / values.length) *
          1_000_000
      ) / 1_000_000,
    median: Math.round(median * 1_000_000) / 1_000_000
  };
}

function overallRows(
  metadata,
  records,
  applications,
  policy,
  diagnostics,
  schema
) {
  const rows = conversionRows(
    metadata,
    applications,
    {
      section: "overall",
      dimension: "overall",
      segment_key: "all",
      segment_label: "All applications"
    },
    policy
  );
  for (const outcome of ["replied", "interview", "offer"]) {
    const numerator = applications.filter((record) =>
      outcomeSet(record).has(outcome)
    ).length;
    rows.push(
      baseRow(metadata, {
        metric_key: `${outcome}_per_ten_applications`,
        numerator,
        denominator: applications.length,
        value: safeDivide(numerator, applications.length, 10),
        unit: "per_10_applications",
        sample_size: applications.length
      })
    );
  }
  const applicationsWithExplicitOutcome = applications.filter(
    (record) => outcomeSet(record).size > 0
  ).length;
  rows.push(
    baseRow(metadata, {
      section: "coverage",
      metric_key: "explicit_outcome_application_coverage",
      numerator: applicationsWithExplicitOutcome,
      denominator: applications.length,
      value: safeDivide(
        applicationsWithExplicitOutcome,
        applications.length
      ),
      unit: "rate",
      sample_size: applications.length,
      coverage_numerator: applicationsWithExplicitOutcome,
      coverage_denominator: applications.length,
      note:
        "Applications without an explicit milestone remain in conversion denominators and are not inferred as no response."
    })
  );

  const reviewHours = [];
  let sameDayReviews = 0;
  let invalidReviewTimestamps = 0;
  for (const record of records) {
    if (!record.first_reviewed_at) continue;
    const discovered = timestamp(record.discovered_at);
    const reviewed = timestamp(record.first_reviewed_at);
    if (
      discovered === undefined ||
      reviewed === undefined ||
      reviewed < discovered
    ) {
      invalidReviewTimestamps += 1;
      continue;
    }
    reviewHours.push((reviewed - discovered) / 3_600_000);
    if (
      dayKey(record.discovered_at, policy.analysis_timezone) ===
      dayKey(record.first_reviewed_at, policy.analysis_timezone)
    ) {
      sameDayReviews += 1;
    }
  }
  const reviewStats = meanAndMedian(reviewHours);
  const reviewHoursSum =
    Math.round(
      reviewHours.reduce((sum, hours) => sum + hours, 0) * 1_000_000
    ) / 1_000_000;
  for (const [metricKey, value, numerator] of [
    ["mean_hours_discovery_to_first_review", reviewStats.mean, reviewHoursSum],
    ["median_hours_discovery_to_first_review", reviewStats.median, ""]
  ]) {
    rows.push(
      baseRow(metadata, {
        section: "time_to_action",
        metric_key: metricKey,
        numerator: value === "" ? "" : numerator,
        denominator: reviewHours.length,
        value,
        unit: "hours",
        sample_size: reviewHours.length,
        coverage_numerator: reviewHours.length,
        coverage_denominator: records.length,
        note: `Day boundaries use ${policy.analysis_timezone}.`
      })
    );
  }
  rows.push(
    baseRow(metadata, {
      section: "time_to_action",
      metric_key: "same_day_first_review_rate",
      numerator: sameDayReviews,
      denominator: reviewHours.length,
      value: safeDivide(sameDayReviews, reviewHours.length),
      unit: "rate",
      sample_size: reviewHours.length,
      coverage_numerator: reviewHours.length,
      coverage_denominator: records.length,
      note: `Same calendar day in ${policy.analysis_timezone}; unobservable or invalid pairs are excluded and disclosed.`
    })
  );

  const applicationHours = [];
  let invalidApplicationTimestamps = 0;
  for (const record of applications) {
    const discovered = timestamp(record.discovered_at);
    const applied = timestamp(record.application_decided_at);
    if (
      discovered === undefined ||
      applied === undefined ||
      applied < discovered
    ) {
      invalidApplicationTimestamps += 1;
      continue;
    }
    applicationHours.push((applied - discovered) / 3_600_000);
  }
  const applicationStats = meanAndMedian(applicationHours);
  const applicationHoursSum =
    Math.round(
      applicationHours.reduce((sum, hours) => sum + hours, 0) * 1_000_000
    ) / 1_000_000;
  for (const [metricKey, value, numerator] of [
    [
      "mean_hours_discovery_to_application",
      applicationStats.mean,
      applicationHoursSum
    ],
    ["median_hours_discovery_to_application", applicationStats.median, ""]
  ]) {
    rows.push(
      baseRow(metadata, {
        section: "time_to_action",
        metric_key: metricKey,
        numerator: value === "" ? "" : numerator,
        denominator: applicationHours.length,
        value,
        unit: "hours",
        sample_size: applicationHours.length,
        coverage_numerator: applicationHours.length,
        coverage_denominator: applications.length
      })
    );
  }

  const knownPointApplications = applications.filter(
    (record) =>
      validContractValue(
        record.apply_points_used,
        schema.field_rules?.apply_points_used
      )
  );
  const knownPoints = knownPointApplications.reduce(
    (sum, record) => sum + record.apply_points_used,
    0
  );
  const replyWithKnownPoints = knownPointApplications.filter((record) =>
    outcomeSet(record).has("replied")
  ).length;
  const interviewWithKnownPoints = knownPointApplications.filter((record) =>
    outcomeSet(record).has("interview")
  ).length;
  const knownConfidencePointApplications = knownPointApplications.filter(
    (record) =>
      validContractValue(
        record.application_ranking_confidence,
        schema.field_rules?.application_ranking_confidence
      )
  );
  const knownConfidencePoints = knownConfidencePointApplications.reduce(
    (sum, record) => sum + record.apply_points_used,
    0
  );
  const highConfidencePoints = knownConfidencePointApplications
    .filter(
      (record) => record.application_ranking_confidence === "high"
    )
    .reduce((sum, record) => sum + record.apply_points_used, 0);
  for (const [metricKey, numerator] of [
    ["replies_per_apply_point", replyWithKnownPoints],
    ["interviews_per_apply_point", interviewWithKnownPoints]
  ]) {
    rows.push(
      baseRow(metadata, {
        section: "apply_point_efficiency",
        metric_key: metricKey,
        numerator,
        denominator: knownPoints,
        value: safeDivide(numerator, knownPoints),
        unit: "per_apply_point",
        sample_size: knownPointApplications.length,
        coverage_numerator: knownPointApplications.length,
        coverage_denominator: applications.length,
        note: "Only known positive actual Apply Points contribute to the denominator."
      })
    );
  }
  rows.push(
    baseRow(metadata, {
      section: "apply_point_efficiency",
      metric_key: "high_confidence_points_share",
      numerator: highConfidencePoints,
      denominator: knownConfidencePoints,
      value: safeDivide(highConfidencePoints, knownConfidencePoints),
      unit: "rate",
      sample_size: knownConfidencePointApplications.length,
      coverage_numerator: knownConfidencePointApplications.length,
      coverage_denominator: applications.length,
      note:
        "Only known valid Apply Points with known application-time confidence contribute to this denominator."
    })
  );
  rows.push(
    baseRow(metadata, {
      section: "coverage",
      metric_key: "known_apply_points_application_coverage",
      numerator: knownPointApplications.length,
      denominator: applications.length,
      value: safeDivide(knownPointApplications.length, applications.length),
      unit: "rate",
      sample_size: applications.length,
      coverage_numerator: knownPointApplications.length,
      coverage_denominator: applications.length
    })
  );

  const gapEvaluated = records.filter(
    (record) =>
      !record.__analytics_malformed_requirement_gap_details &&
      (record.evaluated_at ||
        record.scoring_policy_version ||
        (Array.isArray(record.requirement_gap_details) &&
          record.requirement_gap_details.length > 0))
  );
  const hardGapNonApplications = gapEvaluated.filter(
    (record) =>
      !isApplied(record) &&
      Array.isArray(record.requirement_gap_details) &&
      record.requirement_gap_details.some(
        (gap) => gap?.classification === "hard"
      )
  ).length;
  rows.push(
    baseRow(metadata, {
      section: "avoidance",
      dimension: "requirement_gap",
      segment_key: "hard",
      segment_label: "Hard-gap non-applications",
      metric_key: "hard_gap_non_application_count",
      numerator: hardGapNonApplications,
      denominator: gapEvaluated.length,
      value: hardGapNonApplications,
      unit: "count",
      sample_size: gapEvaluated.length,
      coverage_numerator: gapEvaluated.length,
      coverage_denominator: records.length,
      note: "Counts evaluated jobs with a hard gap and no applied decision; it does not infer causality."
    })
  );

  const packsWithStatus = records.filter((record) =>
    !record.__analytics_malformed_application_warnings &&
    Array.isArray(record.application_warnings) &&
    ["ready", "review_required", "blocked"].includes(
      record.application_pack_status
    )
  );
  const blockedByCode = (codes) =>
    records.filter(
      (record) =>
        record.application_pack_status === "blocked" &&
        Array.isArray(record.application_warnings) &&
        record.application_warnings.some((warning) =>
          codes.includes(warning?.code)
        )
    ).length;
  for (const [metricKey, codes, label] of [
    [
      "packs_blocked_missing_instructions",
      ["description_unavailable"],
      "Missing/unavailable instructions"
    ],
    [
      "packs_blocked_unsupported_evidence",
      ["unsupported_required_evidence"],
      "Unsupported required evidence"
    ]
  ]) {
    const count = blockedByCode(codes);
    rows.push(
      baseRow(metadata, {
        section: "pack_blockers",
        dimension: "application_pack",
        segment_key: metricKey,
        segment_label: label,
        metric_key: metricKey,
        numerator: count,
        denominator: packsWithStatus.length,
        value: count,
        unit: "count",
        sample_size: packsWithStatus.length,
        coverage_numerator: packsWithStatus.length,
        coverage_denominator: records.length
      })
    );
  }

  for (const [metricKey, value] of [
    ["input_row_count", diagnostics.input_rows],
    ["deduplicated_record_count", records.length],
    ["active_archive_overlap_count", diagnostics.overlap_records],
    ["invalid_identity_row_count", diagnostics.invalid_identity_rows],
    [
      "application_snapshot_conflict_count",
      diagnostics.application_snapshot_conflicts
    ],
    [
      "application_decision_conflict_count",
      diagnostics.application_decision_conflicts
    ],
    [
      "malformed_outcome_history_row_count",
      diagnostics.malformed_outcome_history_rows
    ],
    [
      "malformed_requirement_gap_row_count",
      diagnostics.malformed_requirement_gap_rows
    ],
    [
      "malformed_application_warning_row_count",
      diagnostics.malformed_application_warning_rows
    ],
    ["invalid_review_timestamp_count", invalidReviewTimestamps],
    ["invalid_application_timestamp_count", invalidApplicationTimestamps]
  ]) {
    rows.push(
      baseRow(metadata, {
        section: "data_quality",
        metric_key: metricKey,
        numerator: value,
        denominator: diagnostics.input_rows,
        value,
        unit: "count",
        sample_size: diagnostics.input_rows
      })
    );
  }
  return rows;
}

const ANALYTICS_RESULT_FIELDS = [
  "metric_definition_version",
  "band_version",
  "window_type",
  "window_start_at",
  "section",
  "dimension",
  "segment_key",
  "segment_label",
  "metric_key",
  "numerator",
  "denominator",
  "value",
  "unit",
  "sample_size",
  "coverage_numerator",
  "coverage_denominator",
  "attribution",
  "non_additive",
  "note"
];

function analyticsResultKey(rows, summary) {
  const canonicalRows = rows.map((row) =>
    ANALYTICS_RESULT_FIELDS.map((field) => row?.[field] ?? "")
  );
  return stableSha256(
    JSON.stringify({
      key_version: "analytics-result/v1",
      analysis_timezone: summary.analysis_timezone,
      record_count: summary.record_count,
      application_count: summary.application_count,
      attribution_policy: summary.attribution_policy,
      warning_summary: summary.warning_summary,
      rows: canonicalRows
    })
  );
}

function analyticsCompleteMetadataErrors(report) {
  if (!report || typeof report !== "object" || Array.isArray(report)) {
    return ["analytics completion metadata must be an object"];
  }
  const errors = [];
  const versionPattern = /^\d{4}-\d{2}-\d{2}\/v\d+$/;
  const metricVersion = String(report.metric_definition_version || "");
  const reportIdPattern = /^analytics-[a-z0-9-]+-[a-f0-9]{64}$/;
  const generatedAt = timestamp(report.generated_at);
  const windowStart = report.window_start_at
    ? timestamp(report.window_start_at)
    : undefined;
  const windowEnd = timestamp(report.window_end_at);
  const recordCount = Number(report.record_count);
  const applicationCount = Number(report.application_count);
  const detailCount = Number(report.detail_row_count);
  if (report.status !== "complete") {
    errors.push("analytics completion status must be complete");
  }
  if (
    !versionPattern.test(metricVersion) ||
    !versionPattern.test(report.band_version || "")
  ) {
    errors.push("analytics completion versions are invalid");
  }
  if (!reportIdPattern.test(String(report.report_id || ""))) {
    errors.push("analytics completion report identity is invalid");
  }
  if (
    generatedAt === undefined ||
    windowEnd === undefined ||
    generatedAt !== windowEnd ||
    (report.window_start_at && windowStart === undefined) ||
    (windowStart !== undefined && windowStart > windowEnd)
  ) {
    errors.push("analytics completion window is invalid");
  }
  if (report.window_type !== "all_time") {
    errors.push("analytics completion window type is invalid");
  }
  try {
    if (
      typeof report.analysis_timezone !== "string" ||
      !report.analysis_timezone
    ) {
      throw new Error("missing timezone");
    }
    new Intl.DateTimeFormat("en-CA", {
      timeZone: report.analysis_timezone
    }).format(new Date());
  } catch {
    errors.push("analytics completion timezone is invalid");
  }
  if (
    !Number.isInteger(recordCount) ||
    recordCount < 0 ||
    !Number.isInteger(applicationCount) ||
    applicationCount < 0 ||
    applicationCount > recordCount ||
    !Number.isInteger(detailCount) ||
    detailCount < 1
  ) {
    errors.push("analytics completion counts are invalid");
  }
  if (
    typeof report.attribution_policy !== "string" ||
    !report.attribution_policy ||
    typeof report.warning_summary !== "string"
  ) {
    errors.push("analytics completion summary is invalid");
  }
  return errors;
}

function reusableAnalyticsReport(reportRows, completion) {
  const latest = latestCompleteAnalyticsReport(reportRows);
  const rawLatest = (Array.isArray(reportRows) ? [...reportRows] : [])
    .filter(
      (row) =>
        row?.status === "complete" &&
        timestamp(row.generated_at) !== undefined
    )
    .sort(
      (left, right) =>
        timestamp(right.generated_at) - timestamp(left.generated_at) ||
        String(right.report_id).localeCompare(String(left.report_id))
    )[0];
  return latest &&
    rawLatest === latest &&
    latest.report_id === completion.report_id &&
    latest.metric_definition_version === completion.metric_definition_version &&
    latest.band_version === completion.band_version &&
    latest.window_type === completion.window_type &&
    latest.window_start_at === completion.window_start_at &&
    latest.analysis_timezone === completion.analysis_timezone &&
    Number(latest.record_count) === completion.record_count &&
    Number(latest.application_count) === completion.application_count &&
    Number(latest.detail_row_count) === completion.detail_row_count &&
    latest.attribution_policy === completion.attribution_policy &&
    String(latest.warning_summary || "") === completion.warning_summary
    ? latest
    : undefined;
}

function analyticsDetailPersistenceErrors(
  expectedRows,
  persistedRows,
  completion,
  fields
) {
  const expected = Array.isArray(expectedRows) ? expectedRows : [];
  const persisted = Array.isArray(persistedRows) ? persistedRows : [];
  const comparedFields = Array.isArray(fields) ? fields : [];
  const reportId = String(completion?.report_id || "").trim();
  const expectedCount = Number(completion?.detail_row_count);
  const fold = (value) =>
    String(value || "")
      .trim()
      .normalize("NFKC")
      .toLocaleLowerCase("en-US");
  const errors = [];
  if (
    !reportId ||
    !Number.isInteger(expectedCount) ||
    expectedCount < 0 ||
    expected.length !== expectedCount ||
    comparedFields.length === 0
  ) {
    errors.push("analytics detail confirmation input is invalid");
    return errors;
  }
  const expectedKeys = expected.map((row) =>
    fold(row?.analytics_row_id)
  );
  if (
    expectedKeys.some((key) => !key) ||
    new Set(expectedKeys).size !== expectedKeys.length
  ) {
    errors.push("expected analytics detail identities are ambiguous");
    return errors;
  }
  const expectedKeySet = new Set(expectedKeys);
  const reportKey = fold(reportId);
  const relevant = persisted.filter(
    (row) =>
      fold(row?.report_id) === reportKey ||
      expectedKeySet.has(fold(row?.analytics_row_id))
  );
  if (relevant.length !== expectedCount) {
    errors.push("persisted analytics detail count is not exact");
  }
  for (let index = 0; index < expected.length; index += 1) {
    const desired = expected[index];
    const identityKey = expectedKeys[index];
    const matches = relevant.filter(
      (row) => fold(row?.analytics_row_id) === identityKey
    );
    if (matches.length !== 1) {
      errors.push("persisted analytics detail identity is not unique");
      continue;
    }
    if (
      comparedFields.some(
        (field) =>
          String(matches[0]?.[field] ?? "") !==
          String(desired?.[field] ?? "")
      )
    ) {
      errors.push("persisted analytics detail content does not match");
    }
  }
  return [...new Set(errors)];
}

function analyticsSourceIntegrityErrors(detailRows, report) {
  const rows = Array.isArray(detailRows) ? detailRows : [];
  const reportIdValue = String(report?.report_id ?? "");
  const reportIdKey = reportIdValue
    .trim()
    .normalize("NFKC")
    .toLocaleLowerCase("en-US");
  const detailCount = Number(report?.detail_row_count);
  const recordCount = Number(report?.record_count);
  const applicationCount = Number(report?.application_count);
  const errors = [];
  const metadataErrors = analyticsCompleteMetadataErrors(report);
  if (metadataErrors.length > 0 || !reportIdKey) {
    return [
      "analytics source metadata is invalid",
      ...metadataErrors
    ];
  }
  const fold = (value) =>
    String(value ?? "")
      .trim()
      .normalize("NFKC")
      .toLocaleLowerCase("en-US");
  const expectedIds = Array.from(
    { length: detailCount },
    (_, index) =>
      `${reportIdValue}|${String(index + 1).padStart(5, "0")}`
  );
  const expectedIdKeys = new Set(expectedIds.map(fold));
  const relevant = rows.filter((row) => {
    const rowIdKey = fold(row?.analytics_row_id);
    return (
      fold(row?.report_id) === reportIdKey ||
      expectedIdKeys.has(rowIdKey) ||
      rowIdKey.startsWith(`${reportIdKey}|`)
    );
  });
  if (relevant.length !== detailCount) {
    errors.push("analytics source detail count is not exact");
  }
  const metadataFields = [
    "metric_definition_version",
    "band_version",
    "generated_at",
    "window_type",
    "window_start_at",
    "window_end_at"
  ];
  const orderedRows = [];
  for (const expectedId of expectedIds) {
    const expectedIdKey = fold(expectedId);
    const matches = relevant.filter(
      (row) => fold(row?.analytics_row_id) === expectedIdKey
    );
    if (matches.length !== 1) {
      errors.push("analytics source detail identity is not unique");
      continue;
    }
    const row = matches[0];
    orderedRows.push(row);
    if (
      String(row.analytics_row_id ?? "") !== expectedId ||
      String(row.report_id ?? "") !== reportIdValue
    ) {
      errors.push("analytics source detail identity is not exact");
    }
    if (
      metadataFields.some(
        (field) =>
          String(row?.[field] ?? "") !== String(report?.[field] ?? "")
      )
    ) {
      errors.push("analytics source detail metadata does not match");
    }
  }
  if (orderedRows.length === detailCount) {
    const resultKey = analyticsResultKey(orderedRows, {
      analysis_timezone: report.analysis_timezone,
      record_count: recordCount,
      application_count: applicationCount,
      attribution_policy: report.attribution_policy,
      warning_summary: String(report.warning_summary || "")
    });
    const expectedReportId = reportId(
      { metric_definition_version: report.metric_definition_version },
      resultKey
    );
    if (reportIdValue !== expectedReportId) {
      errors.push("analytics source content hash does not match");
    }
  }
  return [...new Set(errors)];
}

function buildAnalyticsReport(
  activeRows,
  archiveRows,
  schema,
  policy,
  now = new Date().toISOString(),
  _options = {}
) {
  const policyErrors = validateAnalyticsPolicy(policy);
  if (policyErrors.length > 0) {
    throw new Error(`Invalid analytics policy:\n- ${policyErrors.join("\n- ")}`);
  }
  if (!Number.isFinite(Date.parse(now))) {
    throw new Error("analytics report timestamp is invalid");
  }
  const { records, diagnostics } = deduplicateAnalyticsRecords(
    activeRows,
    archiveRows,
    schema,
    now
  );
  const applications = records.filter(isApplied);
  const validApplicationTimes = applications
    .map((record) => record.application_decided_at)
    .filter((value) => timestamp(value) !== undefined)
    .sort((left, right) => timestamp(left) - timestamp(right));
  const metadata = {
    report_id: "",
    metric_definition_version: policy.metric_definition_version,
    band_version: policy.band_version,
    generated_at: now,
    window_type: policy.analysis_window.type,
    window_start_at: validApplicationTimes[0] || "",
    window_end_at: now
  };
  const resultRows = [
    ...overallRows(
      metadata,
      records,
      applications,
      policy,
      diagnostics,
      schema
    ),
    ...dimensionsReport(metadata, applications, policy, schema),
    ...discoveryAndSkillDemandRows(metadata, records, policy)
  ];
  const warnings = [];
  if (applications.length === 0) warnings.push("no_applications");
  if (diagnostics.invalid_identity_rows > 0) warnings.push("invalid_identity_rows");
  if (diagnostics.application_snapshot_conflicts > 0) {
    warnings.push("application_snapshot_conflicts");
  }
  if (diagnostics.application_decision_conflicts > 0) {
    warnings.push("application_decision_conflicts");
  }
  if (diagnostics.malformed_outcome_history_rows > 0) {
    warnings.push("malformed_outcome_history_rows");
  }
  if (diagnostics.malformed_requirement_gap_rows > 0) {
    warnings.push("malformed_requirement_gap_rows");
  }
  if (diagnostics.malformed_application_warning_rows > 0) {
    warnings.push("malformed_application_warning_rows");
  }
  metadata.result_key = analyticsResultKey(resultRows, {
    analysis_timezone: policy.analysis_timezone,
    record_count: records.length,
    application_count: applications.length,
    attribution_policy: policy.attribution.policy,
    warning_summary: warnings.join(",")
  });
  metadata.report_id = reportId(policy, metadata.result_key);
  const rows = resultRows.map((row, index) => {
    const completeRow = {
      ...row,
      report_id: metadata.report_id,
      analytics_row_id: `${metadata.report_id}|${String(index + 1).padStart(5, "0")}`
    };
    return Object.fromEntries(
      policy.detail_fields.map((field) => [field, completeRow[field] ?? ""])
    );
  });
  const completion = {
    report_id: metadata.report_id,
    status: "complete",
    metric_definition_version: metadata.metric_definition_version,
    band_version: metadata.band_version,
    generated_at: now,
    window_type: metadata.window_type,
    window_start_at: metadata.window_start_at,
    window_end_at: metadata.window_end_at,
    analysis_timezone: policy.analysis_timezone,
    record_count: records.length,
    application_count: applications.length,
    detail_row_count: rows.length,
    attribution_policy: policy.attribution.policy,
    warning_summary: warnings.join(",")
  };
  return {
    metadata,
    rows,
    completion,
    records,
    diagnostics
  };
}

function latestCompleteAnalyticsReport(reportRows) {
  const rows = Array.isArray(reportRows) ? reportRows : [];
  const latest = [...rows]
    .filter((row) => analyticsCompleteMetadataErrors(row).length === 0)
    .sort(
      (left, right) =>
        timestamp(right.generated_at) - timestamp(left.generated_at) ||
        String(right.report_id).localeCompare(String(left.report_id))
    )[0];
  if (!latest) return undefined;
  const fold = (value) =>
    String(value ?? "")
      .trim()
      .normalize("NFKC")
      .toLocaleLowerCase("en-US");
  const latestKey = fold(latest.report_id);
  return rows.filter((row) => fold(row?.report_id) === latestKey).length === 1
    ? latest
    : undefined;
}


const DIRECTIONAL_STATUS = "recommendation";

function numeric(value) {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (value === "" || value === undefined || value === null) return undefined;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : undefined;
}

function boundedText(value, maximum = 1000) {
  const text = String(value || "")
    .normalize("NFKC")
    .replace(/[\u200b-\u200d\u2060\ufeff]/gi, "")
    .replace(/[\u0000-\u001f\u007f-\u009f]/g, " ")
    .replace(
      /(api[_-]?key|token|authorization|password|secret)\s*[:=]\s*\S+/gi,
      "$1=[redacted]"
    )
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, maximum);
  return /^[=+\-@]/.test(text) ? `'${text}` : text;
}

function version(value) {
  return /^\d{4}-\d{2}-\d{2}\/v\d+$/.test(value ?? "");
}

function arrayEquals(left, right) {
  return JSON.stringify(left) === JSON.stringify(right);
}

function validateRecommendationPolicy(policy) {
  const errors = [];
  if (!policy || typeof policy !== "object" || Array.isArray(policy)) {
    return ["recommendation policy must be an object"];
  }
  if (policy.schema_version !== 1) {
    errors.push("recommendation policy schema_version must be 1");
  }
  for (const field of [
    "policy_version",
    "required_metric_definition_version",
    "required_band_version"
  ]) {
    if (!version(policy[field])) errors.push(`${field} must use YYYY-MM-DD/vN`);
  }
  if (!Number.isInteger(policy.schedule_hours) || policy.schedule_hours < 24) {
    errors.push("schedule_hours must be at least 24");
  }
  errors.push(...validateRecommendationSchedule(policy));
  if (
    !Number.isInteger(policy.execution_timeout_seconds) ||
    policy.execution_timeout_seconds < 1
  ) {
    errors.push("execution_timeout_seconds must be a positive integer");
  } else if (
    Number.isInteger(policy.schedule_hours) &&
    policy.execution_timeout_seconds >= policy.schedule_hours * 60 * 60
  ) {
    errors.push(
      "execution timeout must be shorter than the recommendation schedule"
    );
  }
  if (policy.required_window_type !== "all_time") {
    errors.push("required_window_type must be all_time");
  }
  for (const field of [
    "overall_applications",
    "segment_applications",
    "discovery_volume",
    "promising_requirement_count"
  ]) {
    if (!Number.isInteger(policy.minimums?.[field]) || policy.minimums[field] < 1) {
      errors.push(`minimums.${field} must be a positive integer`);
    }
  }
  for (const field of [
    "explicit_outcome_coverage",
    "dimension_coverage",
    "promising_gap_coverage"
  ]) {
    const value = policy.minimums?.[field];
    if (!Number.isFinite(value) || value < 0 || value > 1) {
      errors.push(`minimums.${field} must be between 0 and 1`);
    }
  }
  if (
    !Number.isFinite(
      policy.comparisons?.minimum_composite_rate_difference
    ) ||
    policy.comparisons.minimum_composite_rate_difference <= 0 ||
    policy.comparisons.minimum_composite_rate_difference > 1
  ) {
    errors.push("minimum composite rate difference must be in (0, 1]");
  }
  if (
    !arrayEquals(policy.comparisons?.composite_outcomes, [
      "reply_rate",
      "interview_rate",
      "offer_rate"
    ])
  ) {
    errors.push(
      "composite outcomes must be reply_rate, interview_rate, and offer_rate"
    );
  }
  if (
    !arrayEquals(policy.score_band_order, [
      "00_24",
      "25_44",
      "45_64",
      "65_79",
      "80_100"
    ])
  ) {
    errors.push("score_band_order is invalid");
  }
  if (!arrayEquals(policy.confidence_order, ["low", "medium", "high"])) {
    errors.push("confidence_order is invalid");
  }
  const expectedDimensions = [
    "matched_skill",
    "salary_band",
    "posting_age_band",
    "apply_points_used",
    "apply_points_recommendation",
    "message_strategy",
    "instruction_completeness"
  ];
  if (!arrayEquals(policy.comparison_dimensions, expectedDimensions)) {
    errors.push("comparison_dimensions are invalid");
  }
  if (
    !Array.isArray(policy.missing_requirement_exclusions) ||
    policy.missing_requirement_exclusions.length === 0
  ) {
    errors.push("missing requirement exclusions are required");
  }
  for (const field of [
    "source_detail_sheet",
    "source_reports_sheet",
    "recommendations_sheet",
    "reports_sheet"
  ]) {
    if (!String(policy[field] || "").trim()) errors.push(`${field} is required`);
  }
  for (const [field, count] of [
    ["recommendation_fields", 28],
    ["report_fields", 19]
  ]) {
    if (
      !Array.isArray(policy[field]) ||
      policy[field].length !== count ||
      new Set(policy[field]).size !== policy[field].length
    ) {
      errors.push(`${field} are invalid`);
    }
  }
  return errors;
}

function analyticsKey(row) {
  return [
    row.dimension || "overall",
    row.segment_key || "all",
    row.metric_key
  ].join("\u001f");
}

function analyticsIndex(rows) {
  return new Map(rows.map((row) => [analyticsKey(row), row]));
}

function metric(index, dimension, segment, metricKey) {
  return index.get([dimension, segment, metricKey].join("\u001f"));
}

function rate(row) {
  return numeric(row?.value);
}

function count(row) {
  return numeric(row?.value) ?? numeric(row?.numerator) ?? 0;
}

function composite(index, dimension, segment) {
  const outcomes = ["reply_rate", "interview_rate", "offer_rate"].map(
    (metricKey) => metric(index, dimension, segment, metricKey)
  );
  const rates = outcomes.map(rate);
  const sampleSize = numeric(outcomes[0]?.denominator);
  if (rates.some((value) => value === undefined) || sampleSize === undefined) {
    return undefined;
  }
  return {
    value:
      Math.round(
        (rates.reduce((sum, value) => sum + value, 0) / outcomes.length) *
          1_000_000
      ) / 1_000_000,
    numerator: outcomes.reduce(
      (sum, row) => sum + (numeric(row.numerator) ?? 0),
      0
    ),
    denominator: sampleSize * outcomes.length,
    sample_size: sampleSize
  };
}

function coverageFor(index, dimension) {
  const row = metric(
    index,
    dimension,
    "all",
    "known_application_coverage"
  );
  return {
    numerator: numeric(row?.coverage_numerator) ?? numeric(row?.numerator) ?? 0,
    denominator:
      numeric(row?.coverage_denominator) ?? numeric(row?.denominator) ?? 0,
    rate: rate(row)
  };
}

function baseEvidence(source, values) {
  return {
    recommendation_id: "",
    run_id: source.run_id,
    analysis_key: source.analysis_key,
    analytics_report_id: source.analytics_report_id,
    recommendation_policy_version: source.policy.policy_version,
    metric_definition_version: source.analytics.metric_definition_version,
    band_version: source.analytics.band_version,
    generated_at: source.generated_at,
    window_start_at: source.analytics.window_start_at || "",
    window_end_at: source.analytics.window_end_at || "",
    status: values.status,
    category: values.category || "",
    affected_type: values.affected_type || "",
    affected_key: boundedText(values.affected_key || "", 500),
    direction: values.direction || "",
    title: boundedText(values.title || "", 500),
    evidence_metric: values.evidence_metric || "",
    numerator: values.numerator ?? "",
    denominator: values.denominator ?? "",
    sample_size: values.sample_size ?? "",
    comparison_value: values.comparison_value ?? "",
    baseline_value: values.baseline_value ?? "",
    difference: values.difference ?? "",
    coverage_numerator: values.coverage_numerator ?? "",
    coverage_denominator: values.coverage_denominator ?? "",
    coverage_rate: values.coverage_rate ?? "",
    proposed_operator_action: boundedText(
      values.proposed_operator_action || "",
      1000
    ),
    caveat: boundedText(values.caveat || "", 1000)
  };
}

function abstention(source, values) {
  return baseEvidence(source, {
    status: "abstained",
    direction: "none",
    caveat:
      values.caveat ||
      "No directional change is justified under the configured sample and coverage rules.",
    ...values
  });
}

function directional(source, values) {
  return baseEvidence(source, {
    status: DIRECTIONAL_STATUS,
    caveat:
      "This is correlational evidence from an observational cohort, not a causal or statistically significant result. Any change requires operator review.",
    ...values
  });
}

function overallGuard(source, index) {
  const applicationCount = count(
    metric(index, "overall", "all", "application_count")
  );
  const outcomeCoverageRow = metric(
    index,
    "overall",
    "all",
    "explicit_outcome_application_coverage"
  );
  const outcomeCoverage = rate(outcomeCoverageRow);
  return {
    applicationCount,
    outcomeCoverage,
    eligible:
      applicationCount >= source.policy.minimums.overall_applications &&
      outcomeCoverage !== undefined &&
      outcomeCoverage >= source.policy.minimums.explicit_outcome_coverage,
    coverageRow: outcomeCoverageRow
  };
}

function queryAndRoleRecommendations(source, index, rows) {
  const result = [];
  const baseline = composite(index, "overall", "all");
  const delta = source.policy.comparisons.minimum_composite_rate_difference;
  for (const dimension of ["search_query", "role_family"]) {
    const coverage = coverageFor(index, dimension);
    if (
      coverage.rate === undefined ||
      coverage.rate < source.policy.minimums.dimension_coverage
    ) {
      result.push(
        abstention(source, {
          category: "search_attention",
          affected_type: dimension,
          affected_key: "all",
          title: `Abstain from ${dimension} recommendations: low coverage`,
          evidence_metric: "known_application_coverage",
          numerator: coverage.numerator,
          denominator: coverage.denominator,
          sample_size: coverage.denominator,
          coverage_numerator: coverage.numerator,
          coverage_denominator: coverage.denominator,
          coverage_rate: coverage.rate
        })
      );
      continue;
    }
    const segments = rows
      .filter(
        (row) =>
          row.dimension === dimension &&
          row.metric_key === "application_count" &&
          row.segment_key !== "unknown"
      )
      .sort((left, right) =>
        String(left.segment_key).localeCompare(String(right.segment_key))
      );
    for (const segment of segments) {
      const sample = count(segment);
      if (sample < source.policy.minimums.segment_applications) continue;
      const observed = composite(index, dimension, segment.segment_key);
      if (!observed || !baseline) continue;
      const difference =
        Math.round((observed.value - baseline.value) * 1_000_000) / 1_000_000;
      const volume = count(
        metric(index, dimension, segment.segment_key, "discovered_job_count")
      );
      if (difference >= delta) {
        result.push(
          directional(source, {
            category: "search_attention",
            affected_type: dimension,
            affected_key: segment.segment_key,
            direction: "increase_attention",
            title: `${segment.segment_label} converts above the overall applied cohort`,
            evidence_metric: "reply_interview_offer_composite",
            numerator: observed.numerator,
            denominator: observed.denominator,
            sample_size: observed.sample_size,
            comparison_value: observed.value,
            baseline_value: baseline.value,
            difference,
            coverage_numerator: coverage.numerator,
            coverage_denominator: coverage.denominator,
            coverage_rate: coverage.rate,
            proposed_operator_action:
              `Review whether to increase manual search attention for ${segment.segment_label}; observed discovery volume is ${volume}.`,
            caveat:
              "Multi-touch full-credit attribution is non-additive, and discovery volume alone is not evidence of conversion."
          })
        );
      } else if (
        (difference <= -delta ||
          (observed.numerator === 0 &&
            volume >= source.policy.minimums.discovery_volume))
      ) {
        result.push(
          directional(source, {
            category: "search_attention",
            affected_type: dimension,
            affected_key: segment.segment_key,
            direction: "reduce_attention",
            title: `${segment.segment_label} has weak response evidence despite observable volume`,
            evidence_metric: "reply_interview_offer_composite",
            numerator: observed.numerator,
            denominator: observed.denominator,
            sample_size: observed.sample_size,
            comparison_value: observed.value,
            baseline_value: baseline.value,
            difference,
            coverage_numerator: coverage.numerator,
            coverage_denominator: coverage.denominator,
            coverage_rate: coverage.rate,
            proposed_operator_action:
              `Review whether to reduce manual search attention for ${segment.segment_label}; observed discovery volume is ${volume}.`,
            caveat:
              "Multi-touch full-credit attribution is non-additive; missing outcomes and selection effects may depress observed conversion."
          })
        );
      }
    }
  }
  return result;
}

function calibrationRecommendations(source, index, rows) {
  const result = [];
  const baseline = composite(index, "overall", "all");
  const delta = source.policy.comparisons.minimum_composite_rate_difference;
  for (const [dimension, order] of [
    ["qualification_score_band", source.policy.score_band_order],
    ["opportunity_score_band", source.policy.score_band_order],
    ["confidence", source.policy.confidence_order]
  ]) {
    const coverage = coverageFor(index, dimension);
    if (
      coverage.rate === undefined ||
      coverage.rate < source.policy.minimums.dimension_coverage
    ) {
      result.push(
        abstention(source, {
          category: "score_calibration",
          affected_type: dimension,
          affected_key: "all",
          title: `Abstain from ${dimension} calibration: low coverage`,
          evidence_metric: "known_application_coverage",
          numerator: coverage.numerator,
          denominator: coverage.denominator,
          sample_size: coverage.denominator,
          coverage_numerator: coverage.numerator,
          coverage_denominator: coverage.denominator,
          coverage_rate: coverage.rate
        })
      );
      continue;
    }
    const eligible = order
      .map((key) => ({
        key,
        observed: composite(index, dimension, key),
        label:
          rows.find(
            (row) =>
              row.dimension === dimension &&
              row.segment_key === key &&
              row.metric_key === "application_count"
          )?.segment_label || key
      }))
      .filter(
        (entry) =>
          entry.observed &&
          entry.observed.sample_size >=
            source.policy.minimums.segment_applications
      );
    for (let indexPosition = 1; indexPosition < eligible.length; indexPosition += 1) {
      const lower = eligible[indexPosition - 1];
      const higher = eligible[indexPosition];
      const difference =
        Math.round(
          (higher.observed.value - lower.observed.value) * 1_000_000
        ) / 1_000_000;
      if (difference <= -delta) {
        result.push(
          directional(source, {
            category: "score_calibration",
            affected_type: dimension,
            affected_key: higher.key,
            direction: "review_overconfidence",
            title: `${higher.label} underperforms the adjacent lower ${dimension} cohort`,
            evidence_metric: "reply_interview_offer_composite",
            numerator: higher.observed.numerator,
            denominator: higher.observed.denominator,
            sample_size: higher.observed.sample_size,
            comparison_value: higher.observed.value,
            baseline_value: lower.observed.value,
            difference,
            coverage_numerator: coverage.numerator,
            coverage_denominator: coverage.denominator,
            coverage_rate: coverage.rate,
            proposed_operator_action:
              "Review the explainable scoring/confidence rules for this band; do not change weights automatically.",
            caveat:
              "The ordered calibration is non-monotonic in this observational cohort; small samples and missing outcomes can cause reversals."
          })
        );
      }
    }
    for (const entry of eligible) {
      if (!baseline) continue;
      const difference =
        Math.round(
          (entry.observed.value - baseline.value) * 1_000_000
        ) / 1_000_000;
      const isLower =
        order.indexOf(entry.key) < Math.floor(order.length / 2);
      if (isLower && difference >= delta) {
        result.push(
          directional(source, {
            category: "score_calibration",
            affected_type: dimension,
            affected_key: entry.key,
            direction: "review_underconfidence",
            title: `${entry.label} outperforms the overall cohort`,
            evidence_metric: "reply_interview_offer_composite",
            numerator: entry.observed.numerator,
            denominator: entry.observed.denominator,
            sample_size: entry.observed.sample_size,
            comparison_value: entry.observed.value,
            baseline_value: baseline.value,
            difference,
            coverage_numerator: coverage.numerator,
            coverage_denominator: coverage.denominator,
            coverage_rate: coverage.rate,
            proposed_operator_action:
              "Review whether the explainable rules underrate this band; retain manual approval for any policy change."
          })
        );
      }
    }
  }
  return result;
}

function comparisonRecommendations(source, index, rows) {
  const result = [];
  const baseline = composite(index, "overall", "all");
  const delta = source.policy.comparisons.minimum_composite_rate_difference;
  for (const dimension of source.policy.comparison_dimensions) {
    const coverage = coverageFor(index, dimension);
    if (
      coverage.rate === undefined ||
      coverage.rate < source.policy.minimums.dimension_coverage
    ) {
      result.push(
        abstention(source, {
          category: "cohort_comparison",
          affected_type: dimension,
          affected_key: "all",
          title: `Abstain from ${dimension} comparison: low coverage`,
          evidence_metric: "known_application_coverage",
          numerator: coverage.numerator,
          denominator: coverage.denominator,
          sample_size: coverage.denominator,
          coverage_numerator: coverage.numerator,
          coverage_denominator: coverage.denominator,
          coverage_rate: coverage.rate
        })
      );
      continue;
    }
    const eligible = rows
      .filter(
        (row) =>
          row.dimension === dimension &&
          row.metric_key === "application_count" &&
          row.segment_key !== "unknown" &&
          count(row) >= source.policy.minimums.segment_applications
      )
      .map((row) => ({
        row,
        observed: composite(index, dimension, row.segment_key)
      }))
      .filter((entry) => entry.observed)
      .sort(
        (left, right) =>
          right.observed.value - left.observed.value ||
          String(left.row.segment_key).localeCompare(
            String(right.row.segment_key)
          )
      );
    if (eligible.length < 2 || !baseline) {
      result.push(
        abstention(source, {
          category: "cohort_comparison",
          affected_type: dimension,
          affected_key: "all",
          title: `Abstain from ${dimension} comparison: insufficient eligible segments`,
          evidence_metric: "eligible_segment_count",
          numerator: eligible.length,
          denominator: 2,
          sample_size: eligible.reduce(
            (sum, entry) => sum + entry.observed.sample_size,
            0
          ),
          coverage_numerator: coverage.numerator,
          coverage_denominator: coverage.denominator,
          coverage_rate: coverage.rate
        })
      );
      continue;
    }
    for (const [entry, direction] of [
      [eligible[0], "favor_for_manual_test"],
      [eligible.at(-1), "review_or_deprioritize"]
    ]) {
      const difference =
        Math.round(
          (entry.observed.value - baseline.value) * 1_000_000
        ) / 1_000_000;
      if (
        (direction === "favor_for_manual_test" && difference < delta) ||
        (direction === "review_or_deprioritize" && difference > -delta)
      ) {
        continue;
      }
      result.push(
        directional(source, {
          category: "cohort_comparison",
          affected_type: dimension,
          affected_key: entry.row.segment_key,
          direction,
          title: `${entry.row.segment_label} differs materially from overall response conversion`,
          evidence_metric: "reply_interview_offer_composite",
          numerator: entry.observed.numerator,
          denominator: entry.observed.denominator,
          sample_size: entry.observed.sample_size,
          comparison_value: entry.observed.value,
          baseline_value: baseline.value,
          difference,
          coverage_numerator: coverage.numerator,
          coverage_denominator: coverage.denominator,
          coverage_rate: coverage.rate,
          proposed_operator_action:
            direction === "favor_for_manual_test"
              ? `Consider a bounded manual test that gives more attention to ${entry.row.segment_label}.`
              : `Review whether to reduce reliance on ${entry.row.segment_label}; do not change policy automatically.`
        })
      );
    }
  }
  return result;
}

function profileSkillSet(profile) {
  const skills = [];
  for (const values of Object.values(profile?.skills ?? {})) {
    if (Array.isArray(values)) skills.push(...values);
  }
  return new Set(
    skills.map((skill) =>
      String(skill).toLowerCase().replace(/[^a-z0-9+#.]+/g, " ").trim()
    )
  );
}

function missingRequirementRecommendations(source, index, rows, profile) {
  const result = [];
  const coverageRow = metric(
    index,
    "missing_requirement",
    "all",
    "promising_job_gap_coverage"
  );
  const coverage = {
    numerator:
      numeric(coverageRow?.coverage_numerator) ??
      numeric(coverageRow?.numerator) ??
      0,
    denominator:
      numeric(coverageRow?.coverage_denominator) ??
      numeric(coverageRow?.denominator) ??
      0,
    rate: rate(coverageRow)
  };
  if (
    coverage.rate === undefined ||
    coverage.rate < source.policy.minimums.promising_gap_coverage
  ) {
    return [
      abstention(source, {
        category: "missing_skill",
        affected_type: "missing_requirement",
        affected_key: "all",
        title: "Abstain from missing-skill recommendations: low promising-job gap coverage",
        evidence_metric: "promising_job_gap_coverage",
        numerator: coverage.numerator,
        denominator: coverage.denominator,
        sample_size: coverage.denominator,
        coverage_numerator: coverage.numerator,
        coverage_denominator: coverage.denominator,
        coverage_rate: coverage.rate
      })
    ];
  }
  const profileSkills = profileSkillSet(profile);
  for (const row of rows
    .filter(
      (candidate) =>
        candidate.dimension === "missing_requirement" &&
        candidate.metric_key === "promising_job_request_count"
    )
    .sort((left, right) =>
      String(left.segment_key).localeCompare(String(right.segment_key))
    )) {
    const requirement = String(row.segment_label || row.segment_key);
    const normalized = requirement
      .toLowerCase()
      .replace(/[^a-z0-9+#.]+/g, " ")
      .trim();
    if (
      source.policy.missing_requirement_exclusions.some((excluded) =>
        normalized.includes(excluded.toLowerCase())
      ) ||
      profileSkills.has(normalized) ||
      count(row) < source.policy.minimums.promising_requirement_count
    ) {
      continue;
    }
    result.push(
      directional(source, {
        category: "missing_skill",
        affected_type: "missing_requirement",
        affected_key: requirement,
        direction: "investigate_skill_development",
        title: `${requirement} is repeatedly requested by promising jobs and absent from approved profile skills`,
        evidence_metric: "promising_job_request_count",
        numerator: numeric(row.numerator) ?? count(row),
        denominator: numeric(row.denominator) ?? coverage.denominator,
        sample_size: numeric(row.sample_size) ?? coverage.denominator,
        comparison_value: count(row),
        baseline_value: "",
        difference: "",
        coverage_numerator: coverage.numerator,
        coverage_denominator: coverage.denominator,
        coverage_rate: coverage.rate,
        proposed_operator_action:
          `Assess whether ${requirement} fits the target direction and whether to learn it; add it to the profile only after factual evidence exists.`,
        caveat:
          `The requirement was absent from approved profile skills at ${profile.profile_version}; frequency does not establish fit, value, or candidate proficiency.`
      })
    );
  }
  if (result.length === 0) {
    result.push(
      abstention(source, {
        category: "missing_skill",
        affected_type: "missing_requirement",
        affected_key: "all",
        title: "No missing requirement meets the guarded recommendation threshold",
        evidence_metric: "eligible_missing_requirement_count",
        numerator: 0,
        denominator: source.policy.minimums.promising_requirement_count,
        sample_size: coverage.denominator,
        coverage_numerator: coverage.numerator,
        coverage_denominator: coverage.denominator,
        coverage_rate: coverage.rate
      })
    );
  }
  return result;
}

function deduplicateEvidence(rows) {
  const values = new Map();
  for (const row of rows) {
    const key = [
      row.status,
      row.category,
      row.affected_type,
      row.affected_key,
      row.direction
    ].join("\u001f");
    if (!values.has(key)) values.set(key, row);
  }
  return [...values.values()];
}

function finalizeRows(source, rows) {
  return deduplicateEvidence(rows).map((row, index) => {
    const complete = {
      ...row,
      recommendation_id: `${source.run_id}|${String(index + 1).padStart(4, "0")}`
    };
    return Object.fromEntries(
      source.policy.recommendation_fields.map((field) => [
        field,
        complete[field] ?? ""
      ])
    );
  });
}

function reportMetadata(source, rows, status, result, error = {}) {
  const recommendationCount = rows.filter(
    (row) => row.status === DIRECTIONAL_STATUS
  ).length;
  const abstentionCount = rows.filter(
    (row) => row.status === "abstained"
  ).length;
  return {
    run_id: source.run_id,
    analysis_key: source.analysis_key,
    status,
    result,
    recommendation_policy_version: source.policy.policy_version,
    analytics_report_id: source.analytics_report_id,
    metric_definition_version:
      source.analytics?.metric_definition_version || "",
    band_version: source.analytics?.band_version || "",
    generated_at: source.generated_at,
    window_start_at: source.analytics?.window_start_at || "",
    window_end_at: source.analytics?.window_end_at || "",
    minimum_overall_applications:
      source.policy.minimums.overall_applications,
    minimum_segment_applications:
      source.policy.minimums.segment_applications,
    minimum_explicit_outcome_coverage:
      source.policy.minimums.explicit_outcome_coverage,
    recommendation_count: recommendationCount,
    abstention_count: abstentionCount,
    detail_row_count: rows.length,
    error_category: error.category || "",
    error_summary: boundedText(error.summary || "", 300)
  };
}

function createSource(
  policy,
  analytics,
  profile,
  now,
  attemptId,
  { stableRunId = false } = {}
) {
  const analyticsReportId = analytics?.report_id || "no-analytics";
  const analysisKey = `recommendation-${stableSha256(
    [
      analyticsReportId,
      policy.policy_version,
      profile?.profile_version || "unknown"
    ].join("\u001f")
  )}`;
  const attempt = String(attemptId || now)
    .replace(/[^a-z0-9_-]/gi, "")
    .slice(0, 64);
  return {
    policy,
    analytics: analytics || {},
    analytics_report_id: analytics?.report_id || "",
    analysis_key: analysisKey,
    run_id: stableRunId
      ? analysisKey
      : `${analysisKey}-${attempt || now.replace(/[^0-9]/g, "")}`,
    generated_at: now
  };
}

function buildRecommendationFailure(
  policy,
  profile,
  now,
  {
    attemptId = "",
    analytics,
    category = "processing_failure",
    summary = "Weekly recommendation processing failed."
  } = {}
) {
  const source = createSource(policy, analytics, profile, now, attemptId);
  const failure = abstention(source, {
    category: "run_health",
    affected_type: "weekly_report",
    affected_key: "all",
    title: "Weekly recommendation run failed",
    evidence_metric: "run_failure",
    caveat:
      "The failure is non-authoritative; retain the last complete weekly report."
  });
  const rows = finalizeRows(source, [failure]);
  return {
    rows,
    report: reportMetadata(source, rows, "failed", "failed", {
      category: boundedText(category, 100),
      summary
    })
  };
}

function buildRecommendationReport(
  analyticsRows,
  analyticsReportRows,
  policy,
  profile,
  now = new Date().toISOString(),
  { attemptId = "" } = {}
) {
  const errors = validateRecommendationPolicy(policy);
  if (errors.length > 0) {
    throw new Error(`Invalid recommendation policy:\n- ${errors.join("\n- ")}`);
  }
  if (!Number.isFinite(Date.parse(now))) {
    throw new Error("recommendation report timestamp is invalid");
  }
  const latest = latestCompleteAnalyticsReport(analyticsReportRows);
  const source = createSource(policy, latest, profile, now, attemptId, {
    stableRunId: true
  });
  if (!latest) {
    const emptyInput =
      analyticsRows.length === 0 && analyticsReportRows.length === 0;
    if (!emptyInput) {
      return buildRecommendationFailure(policy, profile, now, {
        attemptId,
        category: "incomplete_analytics_report",
        summary:
          "Analytics input exists, but no valid complete analytics report is available."
      });
    }
    const rows = finalizeRows(source, [
      abstention(source, {
        status: "empty",
        category: "analytics_input",
        affected_type: "analytics_report",
        affected_key: "all",
        title: "No completed analytics input is available",
        evidence_metric: "complete_analytics_report_count",
        numerator: 0,
        denominator: analyticsReportRows.length,
        sample_size: 0,
        caveat:
          "No search, ranking, profile, strategy, application, or Apply Points setting was changed."
      })
    ]);
    return {
      rows,
      report: reportMetadata(source, rows, "complete", "empty")
    };
  }
  if (
    latest.metric_definition_version !==
      policy.required_metric_definition_version ||
    latest.band_version !== policy.required_band_version ||
    latest.window_type !== policy.required_window_type
  ) {
    return buildRecommendationFailure(policy, profile, now, {
      attemptId,
      analytics: latest,
      category: "incompatible_analytics_version",
      summary:
        "The latest complete analytics report does not match the required metric, band, or window version."
    });
  }
  const sourceIntegrityErrors = analyticsSourceIntegrityErrors(
    analyticsRows,
    latest
  );
  if (sourceIntegrityErrors.length > 0) {
    return buildRecommendationFailure(policy, profile, now, {
      attemptId,
      analytics: latest,
      category: "incomplete_analytics_detail",
      summary:
        "The latest complete analytics metadata does not match its persisted detail rows."
    });
  }
  const rowsForReport = analyticsRows.filter(
    (row) => row.report_id === latest.report_id
  );
  const index = analyticsIndex(rowsForReport);
  const guard = overallGuard(source, index);
  if (guard.applicationCount === 0) {
    const rows = finalizeRows(source, [
      abstention(source, {
        status: "empty",
        category: "overall",
        affected_type: "application_cohort",
        affected_key: "all",
        title: "Completed analytics contains no applications",
        evidence_metric: "application_count",
        numerator: 0,
        denominator: 0,
        sample_size: 0,
        caveat:
          "This is a successful empty weekly report; no policy or profile state was changed."
      })
    ]);
    return {
      rows,
      report: reportMetadata(source, rows, "complete", "empty")
    };
  }
  if (!guard.eligible) {
    const rows = finalizeRows(source, [
      abstention(source, {
        category: "overall",
        affected_type: "application_cohort",
        affected_key: "all",
        title: "Abstain from weekly recommendations: insufficient sample or outcome coverage",
        evidence_metric: "overall_eligibility",
        numerator: guard.applicationCount,
        denominator: source.policy.minimums.overall_applications,
        sample_size: guard.applicationCount,
        comparison_value: guard.outcomeCoverage,
        baseline_value:
          source.policy.minimums.explicit_outcome_coverage,
        coverage_numerator:
          numeric(guard.coverageRow?.coverage_numerator) ??
          numeric(guard.coverageRow?.numerator) ??
          0,
        coverage_denominator:
          numeric(guard.coverageRow?.coverage_denominator) ??
          numeric(guard.coverageRow?.denominator) ??
          guard.applicationCount,
        coverage_rate: guard.outcomeCoverage
      })
    ]);
    return {
      rows,
      report: reportMetadata(source, rows, "complete", "abstained")
    };
  }

  let evidence = [
    ...queryAndRoleRecommendations(source, index, rowsForReport),
    ...calibrationRecommendations(source, index, rowsForReport),
    ...comparisonRecommendations(source, index, rowsForReport),
    ...missingRequirementRecommendations(
      source,
      index,
      rowsForReport,
      profile
    )
  ];
  if (!evidence.some((row) => row.status === DIRECTIONAL_STATUS)) {
    evidence.push(
      abstention(source, {
        category: "overall",
        affected_type: "weekly_report",
        affected_key: "all",
        title: "No eligible cohort produced a directional signal",
        evidence_metric: "directional_recommendation_count",
        numerator: 0,
        denominator: 1,
        sample_size: guard.applicationCount,
        coverage_rate: guard.outcomeCoverage
      })
    );
  }
  const rows = finalizeRows(source, evidence);
  return {
    rows,
    report: reportMetadata(
      source,
      rows,
      "complete",
      rows.some((row) => row.status === DIRECTIONAL_STATUS)
        ? "recommendations"
        : "abstained"
    )
  };
}

function recommendationCompleteMetadataErrors(report) {
  if (!report || typeof report !== "object" || Array.isArray(report)) {
    return ["recommendation completion metadata must be an object"];
  }
  const errors = [];
  const versionPattern = /^\d{4}-\d{2}-\d{2}\/v\d+$/;
  const analysisPattern = /^recommendation-[a-f0-9]{64}$/;
  const analyticsPattern = /^analytics-[a-z0-9-]+-[a-f0-9]{64}$/;
  const generatedAt = Date.parse(report.generated_at || "");
  const windowStart = report.window_start_at
    ? Date.parse(report.window_start_at)
    : undefined;
  const windowEnd = report.window_end_at
    ? Date.parse(report.window_end_at)
    : undefined;
  const overallMinimum = Number(report.minimum_overall_applications);
  const segmentMinimum = Number(report.minimum_segment_applications);
  const coverageMinimum = Number(
    report.minimum_explicit_outcome_coverage
  );
  const recommendationCount = Number(report.recommendation_count);
  const abstentionCount = Number(report.abstention_count);
  const detailCount = Number(report.detail_row_count);
  if (report.status !== "complete") {
    errors.push("recommendation completion status must be complete");
  }
  if (
    !analysisPattern.test(String(report.analysis_key || "")) ||
    report.run_id !== report.analysis_key
  ) {
    errors.push("recommendation completion identity is invalid");
  }
  if (
    !["recommendations", "abstained", "empty"].includes(report.result)
  ) {
    errors.push("recommendation completion result is invalid");
  }
  if (!versionPattern.test(report.recommendation_policy_version || "")) {
    errors.push("recommendation completion policy version is invalid");
  }
  if (!Number.isFinite(generatedAt)) {
    errors.push("recommendation completion timestamp is invalid");
  }
  if (
    !Number.isInteger(overallMinimum) ||
    overallMinimum < 1 ||
    !Number.isInteger(segmentMinimum) ||
    segmentMinimum < 1 ||
    !Number.isFinite(coverageMinimum) ||
    coverageMinimum < 0 ||
    coverageMinimum > 1 ||
    !Number.isInteger(recommendationCount) ||
    recommendationCount < 0 ||
    !Number.isInteger(abstentionCount) ||
    abstentionCount < 0 ||
    !Number.isInteger(detailCount) ||
    detailCount < 1 ||
    recommendationCount + abstentionCount > detailCount
  ) {
    errors.push("recommendation completion counts are invalid");
  }
  const hasAnalytics = Boolean(report.analytics_report_id);
  if (hasAnalytics) {
    if (
      !analyticsPattern.test(String(report.analytics_report_id)) ||
      !versionPattern.test(report.metric_definition_version || "") ||
      !versionPattern.test(report.band_version || "") ||
      !Number.isFinite(windowEnd) ||
      (report.window_start_at && !Number.isFinite(windowStart)) ||
      (Number.isFinite(windowStart) && windowStart > windowEnd)
    ) {
      errors.push("recommendation completion analytics scope is invalid");
    }
  } else if (
    report.result !== "empty" ||
    report.metric_definition_version ||
    report.band_version ||
    report.window_start_at ||
    report.window_end_at
  ) {
    errors.push("recommendation completion empty scope is invalid");
  }
  if (report.error_category || report.error_summary) {
    errors.push("recommendation completion failure fields must be blank");
  }
  return errors;
}

function latestCompleteRecommendationReport(reportRows) {
  const rows = Array.isArray(reportRows) ? reportRows : [];
  const latest = [...rows]
    .filter(
      (row) => recommendationCompleteMetadataErrors(row).length === 0
    )
    .sort(
      (left, right) =>
        Date.parse(right.generated_at) - Date.parse(left.generated_at) ||
        String(right.run_id).localeCompare(String(left.run_id))
    )[0];
  if (!latest) return undefined;
  const fold = (value) =>
    String(value ?? "")
      .trim()
      .normalize("NFKC")
      .toLocaleLowerCase("en-US");
  const latestKey = fold(latest.run_id);
  return rows.filter((row) => fold(row?.run_id) === latestKey).length === 1
    ? latest
    : undefined;
}

function reusableRecommendationReport(reportRows, report) {
  if (report?.status !== "complete") return undefined;
  const latest = latestCompleteRecommendationReport(reportRows);
  const rawLatest = (Array.isArray(reportRows) ? [...reportRows] : [])
    .filter(
      (row) =>
        row?.status === "complete" &&
        Number.isFinite(Date.parse(row.generated_at || ""))
    )
    .sort(
      (left, right) =>
        Date.parse(right.generated_at) - Date.parse(left.generated_at) ||
        String(right.run_id).localeCompare(String(left.run_id))
    )[0];
  return latest &&
    rawLatest === latest &&
    latest.run_id === report.run_id &&
    latest.analysis_key === report.analysis_key &&
    latest.result === report.result &&
    latest.recommendation_policy_version ===
      report.recommendation_policy_version &&
    latest.analytics_report_id === report.analytics_report_id &&
    latest.metric_definition_version === report.metric_definition_version &&
    latest.band_version === report.band_version &&
    latest.window_start_at === report.window_start_at &&
    latest.window_end_at === report.window_end_at &&
    Number(latest.minimum_overall_applications) ===
      report.minimum_overall_applications &&
    Number(latest.minimum_segment_applications) ===
      report.minimum_segment_applications &&
    Number(latest.minimum_explicit_outcome_coverage) ===
      report.minimum_explicit_outcome_coverage &&
    Number(latest.recommendation_count) === report.recommendation_count &&
    Number(latest.abstention_count) === report.abstention_count &&
    Number(latest.detail_row_count) === report.detail_row_count &&
    String(latest.error_category || "") === report.error_category &&
    String(latest.error_summary || "") === report.error_summary
    ? latest
    : undefined;
}

function recommendationDetailPersistenceErrors(
  expectedRows,
  persistedRows,
  report,
  fields
) {
  const expected = Array.isArray(expectedRows) ? expectedRows : [];
  const persisted = Array.isArray(persistedRows) ? persistedRows : [];
  const comparedFields = Array.isArray(fields) ? fields : [];
  const runId = String(report?.run_id || "").trim();
  const expectedCount = Number(report?.detail_row_count);
  const fold = (value) =>
    String(value || "")
      .trim()
      .normalize("NFKC")
      .toLocaleLowerCase("en-US");
  const errors = [];
  if (
    !runId ||
    !Number.isInteger(expectedCount) ||
    expectedCount < 0 ||
    expected.length !== expectedCount ||
    comparedFields.length === 0
  ) {
    errors.push("recommendation detail confirmation input is invalid");
    return errors;
  }
  const expectedKeys = expected.map((row) =>
    fold(row?.recommendation_id)
  );
  if (
    expectedKeys.some((key) => !key) ||
    new Set(expectedKeys).size !== expectedKeys.length
  ) {
    errors.push("expected recommendation detail identities are ambiguous");
    return errors;
  }
  const expectedKeySet = new Set(expectedKeys);
  const runKey = fold(runId);
  const relevant = persisted.filter(
    (row) =>
      fold(row?.run_id) === runKey ||
      expectedKeySet.has(fold(row?.recommendation_id))
  );
  if (relevant.length !== expectedCount) {
    errors.push("persisted recommendation detail count is not exact");
  }
  for (let index = 0; index < expected.length; index += 1) {
    const desired = expected[index];
    const identityKey = expectedKeys[index];
    const matches = relevant.filter(
      (row) => fold(row?.recommendation_id) === identityKey
    );
    if (matches.length !== 1) {
      errors.push("persisted recommendation detail identity is not unique");
      continue;
    }
    if (
      comparedFields.some(
        (field) =>
          String(matches[0]?.[field] ?? "") !==
          String(desired?.[field] ?? "")
      )
    ) {
      errors.push("persisted recommendation detail content does not match");
    }
  }
  return [...new Set(errors)];
}


const REPORT_RETENTION_DAY_MS = 24 * 60 * 60 * 1000;

function nonEmptyString(value) {
  return typeof value === "string" && value.trim().length > 0;
}

function positiveInteger(value) {
  return Number.isInteger(value) && value > 0;
}

function canonicalTimestampMs(value) {
  if (typeof value !== "string" || value.trim() !== value) return Number.NaN;
  const parsed = Date.parse(value);
  if (!Number.isFinite(parsed)) return Number.NaN;
  return new Date(parsed).toISOString() === value ? parsed : Number.NaN;
}

function dataRows(rows) {
  return (Array.isArray(rows) ? rows : []).filter(
    (row) =>
      row &&
      typeof row === "object" &&
      !Array.isArray(row) &&
      Object.keys(row).length > 0
  );
}

function validRowNumber(value) {
  const rowNumber = Number(value);
  return Number.isInteger(rowNumber) && rowNumber >= 2
    ? rowNumber
    : undefined;
}

function uniqueCounts(values) {
  const counts = new Map();
  for (const value of values) {
    if (value === undefined) continue;
    counts.set(value, (counts.get(value) || 0) + 1);
  }
  return counts;
}

function descendingContiguousRanges(rowNumbers) {
  const ascending = [...rowNumbers].sort((left, right) => left - right);
  const ranges = [];
  for (const rowNumber of ascending) {
    const current = ranges.at(-1);
    if (current && rowNumber === current.end_row_number + 1) {
      current.end_row_number = rowNumber;
      current.end_index = rowNumber;
    } else {
      ranges.push({
        start_row_number: rowNumber,
        end_row_number: rowNumber,
        start_index: rowNumber - 1,
        end_index: rowNumber
      });
    }
  }
  return ranges.sort(
    (left, right) => right.start_row_number - left.start_row_number
  );
}

function validateStorePolicy(name, policy) {
  const errors = [];
  const prefix = `${name}.`;
  if (!policy || typeof policy !== "object" || Array.isArray(policy)) {
    return [`${name} retention policy must be an object`];
  }
  if (
    !positiveInteger(policy.retention_days) ||
    policy.retention_days > 3650
  ) {
    errors.push(`${prefix}retention_days must be an integer from 1 through 3650`);
  }
  if (!positiveInteger(policy.minimum_reports_before_cleanup)) {
    errors.push(
      `${prefix}minimum_reports_before_cleanup must be a positive integer`
    );
  }
  if (!positiveInteger(policy.minimum_complete_reports_to_preserve)) {
    errors.push(
      `${prefix}minimum_complete_reports_to_preserve must be a positive integer`
    );
  }
  if (
    !positiveInteger(policy.maximum_reports_per_cleanup) ||
    policy.maximum_reports_per_cleanup > 100
  ) {
    errors.push(
      `${prefix}maximum_reports_per_cleanup must be an integer from 1 through 100`
    );
  }
  if (
    positiveInteger(policy.minimum_reports_before_cleanup) &&
    positiveInteger(policy.minimum_complete_reports_to_preserve) &&
    policy.minimum_reports_before_cleanup <=
      policy.minimum_complete_reports_to_preserve
  ) {
    errors.push(
      `${prefix}minimum_reports_before_cleanup must exceed the preserved complete-report count`
    );
  }
  if (
    !Array.isArray(policy.allowed_statuses) ||
    policy.allowed_statuses.length === 0 ||
    policy.allowed_statuses.some((status) => !nonEmptyString(status))
  ) {
    errors.push(
      `${prefix}allowed_statuses must be a non-empty array of non-empty strings`
    );
  } else if (
    new Set(policy.allowed_statuses.map((status) => status.trim())).size !==
    policy.allowed_statuses.length
  ) {
    errors.push(`${prefix}allowed_statuses must not contain duplicates`);
  }
  if (!nonEmptyString(policy.claim_identity)) {
    errors.push(`${prefix}claim_identity must be a non-empty string`);
  }
  if (!nonEmptyString(policy.claim_stage)) {
    errors.push(`${prefix}claim_stage must be a non-empty string`);
  }
  if (
    !positiveInteger(policy.claim_lease_ms) ||
    policy.claim_lease_ms > REPORT_RETENTION_DAY_MS
  ) {
    errors.push(`${prefix}claim_lease_ms must be from 1 through 86400000`);
  }
  return errors;
}

function validateReportRetentionPolicy(policy) {
  const errors = [];
  if (!policy || typeof policy !== "object" || Array.isArray(policy)) {
    return ["report retention policy must be an object"];
  }
  if (!positiveInteger(policy.schema_version)) {
    errors.push("schema_version must be a positive integer");
  }
  if (!nonEmptyString(policy.policy_version)) {
    errors.push("policy_version must be a non-empty string");
  }
  if (typeof policy.enabled !== "boolean") {
    errors.push("enabled must be a boolean");
  }
  errors.push(...validateStorePolicy("analytics", policy.analytics));
  errors.push(
    ...validateStorePolicy("recommendations", policy.recommendations)
  );
  if (
    nonEmptyString(policy.analytics?.claim_identity) &&
    policy.analytics.claim_identity === policy.recommendations?.claim_identity
  ) {
    errors.push("report-store claim identities must be distinct");
  }
  return errors;
}

function retentionCandidates(
  reportRows,
  storePolicy,
  { reportIdField, now }
) {
  const rows = dataRows(reportRows);
  const nowMs = canonicalTimestampMs(now);
  if (!Number.isFinite(nowMs)) {
    throw new Error("report retention planning time must be canonical ISO-8601");
  }
  const cutoffMs =
    nowMs - storePolicy.retention_days * REPORT_RETENTION_DAY_MS;
  const allowedStatuses = new Set(storePolicy.allowed_statuses);
  const idCounts = uniqueCounts(
    rows.map((row) => {
      const id = String(row?.[reportIdField] || "").trim();
      return id || undefined;
    })
  );
  const rowNumberCounts = uniqueCounts(
    rows.map((row) => validRowNumber(row.row_number))
  );
  const validComplete = rows
    .map((row) => ({
      row,
      id: String(row?.[reportIdField] || "").trim(),
      generatedAtMs: canonicalTimestampMs(row?.generated_at)
    }))
    .filter(
      ({ id, generatedAtMs }) =>
        id &&
        idCounts.get(id) === 1 &&
        Number.isFinite(generatedAtMs)
    );
  const preservedCompleteIds = new Set(
    validComplete
      .filter(({ row }) => row.status === "complete")
      .sort(
        (left, right) =>
          right.generatedAtMs - left.generatedAtMs ||
          right.id.localeCompare(left.id)
      )
      .slice(0, storePolicy.minimum_complete_reports_to_preserve)
      .map(({ id }) => id)
  );
  const eligible = [];
  const counts = {
    reports_seen: rows.length,
    eligible: 0,
    selected: 0,
    deferred: 0,
    preserved_recent_or_current: 0,
    preserved_malformed_or_ambiguous: 0,
    preserved_unsupported_status: 0,
    preserved_incomplete_detail: 0
  };
  for (const row of rows) {
    const id = String(row?.[reportIdField] || "").trim();
    const rowNumber = validRowNumber(row.row_number);
    const generatedAtMs = canonicalTimestampMs(row.generated_at);
    const detailRowCount = Number(row.detail_row_count);
    if (
      !id ||
      idCounts.get(id) !== 1 ||
      rowNumber === undefined ||
      rowNumberCounts.get(rowNumber) !== 1 ||
      !Number.isFinite(generatedAtMs) ||
      !Number.isInteger(detailRowCount) ||
      detailRowCount < 0
    ) {
      counts.preserved_malformed_or_ambiguous += 1;
      continue;
    }
    if (!allowedStatuses.has(String(row.status || ""))) {
      counts.preserved_unsupported_status += 1;
      continue;
    }
    if (generatedAtMs >= cutoffMs || preservedCompleteIds.has(id)) {
      counts.preserved_recent_or_current += 1;
      continue;
    }
    eligible.push({
      id,
      report_row_number: rowNumber,
      detail_row_count: detailRowCount,
      generated_at_ms: generatedAtMs
    });
  }
  eligible.sort(
    (left, right) =>
      left.generated_at_ms - right.generated_at_ms ||
      left.id.localeCompare(right.id)
  );
  counts.eligible = eligible.length;
  return {
    rows,
    eligible,
    counts,
    cutoff_at: new Date(cutoffMs).toISOString(),
    threshold_reached:
      rows.length >= storePolicy.minimum_reports_before_cleanup
  };
}

function reportRetentionCandidateStatus(
  reportRows,
  policy,
  storeName,
  { reportIdField, now = new Date().toISOString() }
) {
  const errors = validateReportRetentionPolicy(policy);
  if (errors.length > 0) {
    throw new Error(`Invalid report retention policy:\n- ${errors.join("\n- ")}`);
  }
  const storePolicy = policy[storeName];
  if (!storePolicy) throw new Error(`Unknown report store: ${storeName}`);
  const plan = retentionCandidates(reportRows, storePolicy, {
    reportIdField,
    now
  });
  return {
    policy_version: policy.policy_version,
    store: storeName,
    enabled: policy.enabled,
    threshold_reached: plan.threshold_reached,
    retention_cutoff_at: plan.cutoff_at,
    reports_seen: plan.counts.reports_seen,
    eligible: plan.counts.eligible,
    cleanup_required:
      policy.enabled &&
      plan.threshold_reached &&
      plan.counts.eligible > 0
  };
}

function planReportRetention(
  reportRows,
  detailRows,
  policy,
  storeName,
  {
    reportIdField,
    detailReportIdField,
    detailIdField,
    now = new Date().toISOString()
  }
) {
  const errors = validateReportRetentionPolicy(policy);
  if (errors.length > 0) {
    throw new Error(`Invalid report retention policy:\n- ${errors.join("\n- ")}`);
  }
  const storePolicy = policy[storeName];
  if (!storePolicy) throw new Error(`Unknown report store: ${storeName}`);
  const candidatePlan = retentionCandidates(reportRows, storePolicy, {
    reportIdField,
    now
  });
  const details = dataRows(detailRows);
  const detailRowNumberCounts = uniqueCounts(
    details.map((row) => validRowNumber(row.row_number))
  );
  const detailsByReport = new Map();
  for (const row of details) {
    const reportId = String(row?.[detailReportIdField] || "").trim();
    if (!reportId) continue;
    if (!detailsByReport.has(reportId)) detailsByReport.set(reportId, []);
    detailsByReport.get(reportId).push(row);
  }

  const selected = [];
  for (const candidate of candidatePlan.eligible) {
    if (
      selected.length >= storePolicy.maximum_reports_per_cleanup
    ) {
      break;
    }
    const reportDetails = detailsByReport.get(candidate.id) || [];
    const detailIds = reportDetails.map((row) =>
      String(row?.[detailIdField] || "").trim()
    );
    const uniqueDetailIds = new Set(detailIds);
    const validDetails =
      reportDetails.length === candidate.detail_row_count &&
      detailIds.every(Boolean) &&
      uniqueDetailIds.size === detailIds.length &&
      reportDetails.every((row) => {
        const rowNumber = validRowNumber(row.row_number);
        return (
          rowNumber !== undefined &&
          detailRowNumberCounts.get(rowNumber) === 1
        );
      });
    if (!validDetails) {
      candidatePlan.counts.preserved_incomplete_detail += 1;
      continue;
    }
    selected.push({
      ...candidate,
      detail_row_numbers: reportDetails.map((row) =>
        validRowNumber(row.row_number)
      )
    });
  }

  candidatePlan.counts.selected = selected.length;
  candidatePlan.counts.deferred =
    candidatePlan.counts.eligible -
    selected.length -
    candidatePlan.counts.preserved_incomplete_detail;
  const enabled = policy.enabled && candidatePlan.threshold_reached;
  const committedSelection = enabled ? selected : [];
  return {
    policy_version: policy.policy_version,
    store: storeName,
    enabled: policy.enabled,
    threshold_reached: candidatePlan.threshold_reached,
    planned_at: now,
    retention_cutoff_at: candidatePlan.cutoff_at,
    counts: {
      ...candidatePlan.counts,
      selected: committedSelection.length
    },
    selected_report_ids: committedSelection.map(({ id }) => id),
    report_delete_ranges: descendingContiguousRanges(
      committedSelection.map(({ report_row_number }) => report_row_number)
    ),
    detail_delete_ranges: descendingContiguousRanges(
      committedSelection.flatMap(({ detail_row_numbers }) => detail_row_numbers)
    )
  };
}


